    if (paired.length > 0) {
      handleGenerate(itemId, `[ACTION:TRANSPLANT] Precise design transplant using mapped keypoints.`);
      return;
    }

    // 逻辑 B: 语义重构闭环 (重写强化 Prompt)
    const modified = points.filter(p => p.modifiedDescription || p.isRemoving);
    if (modified.length > 0) {
      const restructureInstructions = modified.map(p => {
        if (p.isRemoving) return `- Anchor Point [${p.label}] at Normalized Coordinate [y=${Math.round(p.y)}, x=${Math.round(p.x)}]: MANDATORY REMOVAL. Heal surrounding surface topology naturally.`;
        return `- Anchor Point [${p.label}] at Normalized Coordinate [y=${Math.round(p.y)}, x=${Math.round(p.x)}]: OVERRIDE with "${p.modifiedDescription}". Recalculate material and geometric detail.`;
      }).join('\n');

      const finalPrompt = `[SEMANTIC RESTRUCTURE PROTOCOL]:
MANDATE: Prioritize the following semantic overrides over the existing image pixel values at the specified anchor locations.
INSTRUCTIONS:
${restructureInstructions}
TECHNICAL SPEC: Maintain 100% silhouette consistency. Execute pixel-level semantic replacement.`;

      // 使用较高的 artisticLevel 以确保模型遵循指令执行大规模局部改动
