        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
        const data = imageBase64.split(',')[1] || imageBase64; 
        const mimeType = imageBase64.split(';')[0].split(':')[1] || 'image/jpeg';
        const response = await ai.models.generateContent({ 
            model, 
            contents: [{ parts: [{ inlineData: { data, mimeType } }, { text: `Visual variation of this. Maintain perspective and silhouette. Style: ${styleSuffix}.` }] }], 
            config: { imageConfig: { aspectRatio: normalizeAspectRatio(ratio) as any } } 
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Variation failed.");
    });
};

