             lastGenerated={null} 
             externalRef={externalRefImage} 
             onExternalRefConsumed={() => setExternalRefImage(null)}
             onGenerate={(p, style, ratio, refs, count, level, res, recipeId, usePro) => handleGenerate('', p, { style, ratio, imageCount: count, artisticLevel: level, resolution: res, recipeId, usePro }, refs)}
             onExportRecipes={handleExportRecipes}
             onImportRecipes={handleImportRecipes}
