  const handleGenerate = async (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>, manualRefs?: string[]) => {
    const rawPrompt = overridePrompt || (items.find(i => i.id === id)?.prompt || "Professional design");
    if (rawPrompt === '__START_PICK_POINT__') { handleStartPickPoint(id, settings?.artisticLevel || 0.8); return; }
    lastGenerationRef.current = { id, prompt: overridePrompt, settings, refs: manualRefs };
    const sourceItem = id ? items.find(i => i.id === id) : null; 
    let contextItem: CanvasItem | null = id ? (sourceItem || null) : null;
    const { tasks, isEvolution, level } = parseGenerationIntent(rawPrompt, contextItem, settings);
    if (isEvolution && level !== undefined) setCurrentEvolutionLevel(level);

    let targetW = 512, targetH = 512; 
    let ratioToUse = settings?.ratio || '1:1';
    if (contextItem) { targetW = contextItem.width; targetH = contextItem.height; ratioToUse = contextItem.aspectRatio || ratioToUse; } 
    else if (manualRefs && manualRefs.length > 0) { const dims = await getImageDimensions(manualRefs[0]); targetW = dims.width; targetH = dims.height; ratioToUse = getClosestAspectRatio(dims.width, dims.height); } 
    else { const ratioObj = ASPECT_RATIOS.find(r => r.id === ratioToUse) || ASPECT_RATIOS[0]; targetW = ratioObj.width; targetH = ratioObj.height; }

    const styleId = settings?.style || 'industrial'; 
    const styleObj = STYLES.find(s => s.id === styleId) || STYLES[1];
    let recipeTxt = "";
    if (settings?.recipeId) { const recipes = await getAllRecipes(); const targetRecipe = recipes.find(r => r.id === settings.recipeId); if (targetRecipe) recipeTxt = targetRecipe.instruction; }

    const usePro = settings?.usePro || false;

    let currentTempItems = [...items];
    tasks.forEach((t, nid) => {
        const spot = findPlacementSpot(targetW, targetH, currentTempItems, contextItem, nid);
        const placeholder: CanvasItem = { id: t.nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: targetW, height: targetH, rotation: contextItem?.rotation || 0, content: '', status: 'loading', prompt: t.prompt, aspectRatio: ratioToUse, links: contextItem ? [contextItem.id] : [] };
        currentTempItems.push(placeholder);
    });
    setItems(currentTempItems); commit(currentTempItems); setSelection(tasks.map(t => t.nid));

    tasks.forEach(async (task) => {
        try {
            let url: string;
            const currentArtisticLevel = settings?.artisticLevel ?? 50;
            const resolution = settings?.resolution || '1K';
            if (task.prompt === '[ACTION: VARIATION]' && contextItem && contextItem.content) {
                url = await generateTopologyVariation(contextItem.content, ratioToUse, styleObj.promptSuffix, usePro);
            }
            else if (task.prompt === '__VISUAL_PEEL__' && contextItem && contextItem.content) {
                url = await generateVisualPeel(contextItem.content, ratioToUse, usePro);
            }
            else if (task.prompt.startsWith('inference:') && contextItem && contextItem.content) {
                const infParams = task.prompt.split(':')[1].split('|');
                const prompt = infParams[0];
                const influence = parseFloat(infParams[1]);
                const recipeId = infParams[3];
                const subType = infParams[4];
                url = await generateWithReferences(prompt, [{ label: 'Source Volume', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, currentArtisticLevel, resolution, settings?.spatialConfig || contextItem.spatialConfig, recipeTxt, { prompt, influence, style: styleObj.id, recipeId, subjectType: subType as any }, usePro);
            }
            else if (contextItem && contextItem.content) { 
                const refs = [{ label: 'Source', base64: contextItem.content }];
                if (task.prompt.includes('[ACTION:TRANSPLANT]')) {
                    const firstPairedPoint = contextItem.identifiedPoints?.find(p => p.pairingId);
                    if (firstPairedPoint) { const styleRef = items.find(si => si.id === firstPairedPoint.pairingSourceItemId); if (styleRef?.content) refs.push({ label: 'Aesthetic Reference', base64: styleRef.content }); }
                }
                url = await generateWithReferences(task.prompt, refs, ratioToUse, styleObj.promptSuffix, currentArtisticLevel, resolution, settings?.spatialConfig || contextItem.spatialConfig, recipeTxt, undefined, usePro); 
            }
            else if (manualRefs && manualRefs.length > 0) { 
                const refs = manualRefs.map((r, nid) => ({ label: `Ref ${nid}`, base64: r })); 
                url = await generateWithReferences(task.prompt, refs, ratioToUse, styleObj.promptSuffix, currentArtisticLevel, resolution, settings?.spatialConfig, recipeTxt, undefined, usePro); 
            }
            else { 
                url = await generateImage(task.prompt, styleObj.promptSuffix, ratioToUse, currentArtisticLevel, resolution, settings?.spatialConfig, recipeTxt, usePro); 
            }
            const { width, height } = await getImageDimensions(url); 
            setItems(prev => prev.map(i => i.id === task.nid ? { ...i, content: url, status: 'generated', height: (height * i.width) / width, aspectRatio: getClosestAspectRatio(width, height) } : i));
        } catch (e: any) { setItems(prev => prev.map(i => i.id === task.nid ? { ...i, status: 'error' } : i)); }
    });
  };

  const handleFrameAction = useCallback(async (frameId: string, action: 'merge' | 'expand' | 'crop' | 'explode', options?: any) => {
    const frame = items.find(i => i.id === frameId);
    if (!frame || frame.type !== ItemType.FRAME) return;

    const children = items.filter(it => 
        it.id !== frame.id && it.type === ItemType.IMAGE && it.content &&
        (it.x + it.width/2) >= frame.x && (it.x + it.width/2) <= frame.x + frame.width && 
        (it.y + it.height/2) >= frame.y && (it.y + it.height/2) <= frame.y + frame.height
    );

    if (action === 'merge') {
        if (children.length === 0) { alert("画框内没有可融合的图像。"); return; }
        const refs = children.map((c, nid) => ({ label: `Subject ${nid + 1}`, base64: c.content }));
        const prompt = frame.prompt || "Seamless scene integration.";
        const ratio = getClosestAspectRatio(frame.width, frame.height);
        const nid = crypto.randomUUID();
        const placeholder: CanvasItem = { id: nid, type: ItemType.IMAGE, x: frame.x, y: frame.y, width: frame.width, height: frame.height, rotation: 0, content: '', status: 'loading', prompt, links: children.map(c => c.id) };
        const nextItems = [...items, placeholder];
        setItems(nextItems); commit(nextItems); setSelection([nid]);
        try {
            const url = await generateWithReferences(prompt, refs, ratio, STYLES[1].promptSuffix, 0.8, '1K');
            setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated' } : i));
        } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
    } else if (action === 'explode') {
        if (children.length === 0) { alert("请在画框内放置至少一张图像执行分离。"); return; }
        const mainImg = children[0];
        setIsAnalyzingJSON(true);
        try {
            const isDeep = options?.deep === true;
            const result = await detectImageJSONSegments(mainImg.content, isDeep);
            if (!result.segments || result.segments.length === 0) { throw new Error("无法识别元素"); }

            const ratio = mainImg.aspectRatio || '1:1';
            const subjectSegments = result.segments.filter((s: any) => s.type === 'subject');
            const combinedMask = createCombinedMask(subjectSegments.map((s: any) => s.box_2d));

            // 1. 生成“去主体”背景底图
            const backgroundUrl = await inpaintBackground(mainImg.content, combinedMask, ratio);
            const parentId = crypto.randomUUID();
            const parentItem: CanvasItem = {
                ...mainImg,
                id: parentId,
                content: backgroundUrl,
                status: 'generated',
                prompt: 'Clean Background Layer'
            };

            const nextItems = [...items.filter(it => it.id !== mainImg.id), parentItem];
            setItems(nextItems);
            setSelection([parentId]);

            // 2. 异步处理透明零件
            subjectSegments.forEach(async (seg: any) => {
                const subNid = crypto.randomUUID();
                const [ymin, xmin, ymax, xmax] = seg.box_2d;
                const sw = (xmax - xmin) / 1000 * mainImg.width;
                const sh = (ymax - ymin) / 1000 * mainImg.height;
                const sx = mainImg.x + (xmin / 1000 * mainImg.width);
                const sy = mainImg.y + (ymin / 1000 * mainImg.height);

                // 占位
                const placeholder: CanvasItem = {
                    id: subNid, type: ItemType.IMAGE,
                    x: sx, y: sy, width: sw, height: sh,
                    rotation: mainImg.rotation, content: '',
                    status: 'loading', parentId: parentId, isChild: true, isTransparent: true,
                    prompt: seg.label, essence: seg.description
                };
                setItems(prev => [...prev, placeholder]);

                try {
                    // 先物理裁剪，再发给 AI 去背景，确保精度
                    const rawCrop = await cropImageSegment(mainImg.content, seg.box_2d);
                    const transparentUrl = await removeBackground(rawCrop, '1:1');
                    setItems(prev => prev.map(it => it.id === subNid ? { ...it, content: transparentUrl, status: 'generated' } : it));
                } catch (e) {
                    setItems(prev => prev.map(it => it.id === subNid ? { ...it, status: 'error' } : it));
                }
            });

        } catch (e) {
            alert("深度解构失败，请重试。");
        } finally {
            setIsAnalyzingJSON(false);
        }
    } else if (action === 'expand') {
        if (children.length === 0) return;
        const main = children[0];
        handleGenerate(main.id, "Expand background seamlessly", { ratio: getClosestAspectRatio(frame.width, frame.height) });
    } else if (action === 'crop') {
        if (children.length === 0) return;
        const target = children[0];
        const nextItems = items.map(it => it.id === target.id ? { ...it, x: frame.x, y: frame.y, width: frame.width, height: frame.height } : it).filter(it => it.id !== frame.id);
        setItems(nextItems); commit(nextItems); setSelection([target.id]);
    }
  }, [items, commit, handleGenerate, setItems]);

  // --- 修复：添加缺失的项目导出逻辑 ---
  const handleExportProject = useCallback(() => {
    const pkg: ProjectPackage = { version: '1.0', timestamp: Date.now(), items, view };
    const blob = new Blob([JSON.stringify(pkg, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `imagination_project_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, [items, view]);

  const handleImportProject = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const pkg = JSON.parse(e.target?.result as string) as ProjectPackage;
        if (pkg.items && Array.isArray(pkg.items)) {
          setItems(pkg.items);
          if (pkg.view) setView(pkg.view);
          resetHistory(pkg.items);
        }
      } catch (err) { alert("导入失败：文件格式错误"); }
    };
    reader.readAsText(file);
  }, [setItems, setView, resetHistory]);

  // --- 修复：添加云同步逻辑 ---
  const handleCloudSave = async () => {
    const pkg: ProjectPackage = { version: '1.0', timestamp: Date.now(), items, view };
    await uploadProjectToCloud(pkg);
  };

  const handleCloudLoad = async () => {
    const pkg = await downloadProjectFromCloud();
    setItems(pkg.items);
    if (pkg.view) setView(pkg.view);
    resetHistory(pkg.items);
  };

  // --- 修复：添加元素操作与录制逻辑 ---
  const addItem = useCallback((item: CanvasItem) => {
    const nextItems = [...items, item];
    setItems(nextItems);
    commit(nextItems);
  }, [items, setItems, commit]);

  const startRecording = async (res: string) => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
      streamRef.current = stream;
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      recordedChunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `recording_${Date.now()}.webm`;
        a.click();
      };
      recorder.start();
      setRecordingStatus('recording');
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => setRecordingTime(t => t + 1), 1000);
    } catch (e) { console.error(e); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) mediaRecorderRef.current.stop();
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    if (timerRef.current) clearInterval(timerRef.current);
    setRecordingStatus('idle');
  };

  // --- 修复：添加 3D 模型交互回调 ---
  const onCameraChange = useCallback((id: string, spatial: SpatialConfig) => {
    handleUpdateItem(id, { spatialConfig: spatial });
  }, [handleUpdateItem]);

  const onLoadParts = useCallback((id: string, parts: string[]) => {
    handleUpdateItem(id, { partList: parts });
  }, [handleUpdateItem]);

  // --- 修复：添加食谱导入导出逻辑 ---
  const handleExportRecipes = useCallback(async () => {
    const recipes = await getAllRecipes();
    const blob = new Blob([JSON.stringify(recipes, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `design_recipes_${Date.now()}.json`;
    a.click();
  }, []);

  const handleImportRecipes = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const recipes = JSON.parse(e.target?.result as string) as DesignRecipe[];
        for (const r of recipes) { await saveRecipe(r); }
        setRecipeRefreshTrigger(t => t + 1);
      } catch (err) { alert("导入食谱失败"); }
    };
    reader.readAsText(file);
  }, []);

  const handleSaveRecipe = async (name: string, instruction: string) => {
    if (!recipePanelData) return;
    const newRecipe: DesignRecipe = {
      id: crypto.randomUUID(), name, instruction,
      exampleImages: recipePanelData.images, createdAt: Date.now()
    };
    await saveRecipe(newRecipe);
    setRecipePanelData(null);
    setRecipeRefreshTrigger(t => t + 1);
  };

  // --- 修复：添加上下文菜单处理逻辑 ---
  const handleContextMenuAction = (action: string, itemId?: string) => {
    setContextMenu(null);
    const targetId = itemId || (selection.length === 1 ? selection[0] : null);
    if (!targetId && action !== 'frame' && action !== 'upload') return;

    switch(action) {
      case 'delete': handleDeleteItems(selection.includes(targetId!) ? selection : [targetId!]); break;
      case 'copy': handleCopy(targetId); break;
      case 'variations': if (targetId) handleGenerate(targetId, '[ACTION: VARIATION]'); break;
      case 'frame': addItem({ id: crypto.randomUUID(), type: ItemType.FRAME, x: 0, y: 0, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' }); break;
      case 'upload': fileInputRef.current?.click(); break;
      case 'send_to_gemini': if (targetId) chatRef.current?.addExternalAttachment(targetId, items.find(i => i.id === targetId)?.content || ''); break;
      case 'send_to_prompt': if (targetId) setExternalRefImage(items.find(i => i.id === targetId)?.content || null); break;
      case 'frame_selection': 
        const selectedItemsList = items.filter(i => selection.includes(i.id));
        if (selectedItemsList.length > 0) {
          const minX = Math.min(...selectedItemsList.map(i => i.x));
          const minY = Math.min(...selectedItemsList.map(i => i.y));
          const maxX = Math.max(...selectedItemsList.map(i => i.x + i.width));
          const maxY = Math.max(...selectedItemsList.map(i => i.y + i.height));
          addItem({ id: crypto.randomUUID(), type: ItemType.FRAME, x: minX - 20, y: minY - 20, width: maxX - minX + 40, height: maxY - minY + 40, rotation: 0, content: 'Selection Frame', status: 'empty' });
        }
        break;
    }
  };

  const handleCaptureRegion = useCallback(async (region: Rect, action: 'chat' | 'canvas' | 'translate', capturedImage?: string | null, annotations?: any[]) => {
    const overlappingItems = items.filter(i => i.x < region.x + region.width && i.x + i.width > region.x && i.y < region.y + region.height && i.y + i.width > region.x);
    const finalData = capturedImage || (overlappingItems.length > 0 ? overlappingItems[0].content : null);
    if (!finalData) { alert("无法捕获内容"); return; }
    if (action === 'chat' && chatRef.current) { chatRef.current.addExternalAttachment('screenshot', finalData); } 
    else if (action === 'canvas') {
        const spot = findPlacementSpot(512, 512, items);
        const screenshotItem: CanvasItem = { id: crypto.randomUUID(), type: ItemType.IMAGE, x: spot.x, y: spot.y, width: 512, height: 512, rotation: 0, content: finalData, status: 'generated', prompt: "Screenshot Fragment" };
        setItems([...items, screenshotItem]);
        handleGenerate(screenshotItem.id, "Visual variation");
    }
    setTool('select');
  }, [items, findPlacementSpot, handleGenerate, setItems]);

  const handleApplyEdit = useCallback(async (prompt: string) => {
    if (!selectedItem || !canvasRef.current) return;
    const maskData = await canvasRef.current.getMaskData();
    if (!maskData) return;
    const nid = crypto.randomUUID();
    setItems([...items, { ...selectedItem, id: nid, content: '', status: 'loading', prompt, links: [selectedItem.id] }]);
    setSelection([nid]);
    try {
      const url = await editImage(selectedItem.content, prompt, selectedItem.aspectRatio || '1:1', maskData.mask);
      setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated' } : i));
    } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
  }, [selectedItem, items, commit, setItems]);

  const handleJSONAnalysis = useCallback(async (id: string) => {
    const item = items.find(i => i.id === id); if (!item || !item.content) return;
    setIsAnalyzingJSON(true);
    try { const result = await detectImageJSONSegments(item.content); if (result.segments) setSegments(result.segments); } 
    catch (e) { console.error(e); } finally { setIsAnalyzingJSON(false); }
  }, [items]);

  const handleUpdatePoint = useCallback((itemId: string, pointId: string, updates: Partial<IdentifiedPoint>) => {
    setItems(prev => prev.map(it => it.id === itemId ? { ...it, identifiedPoints: it.identifiedPoints?.map(p => p.id === pointId ? { ...p, ...updates } : p) } : it));
  }, [setItems]);

  const handleClearAllPoints = useCallback((itemId: string) => {
    setItems(items.map(it => it.id === itemId ? { ...it, identifiedPoints: [] } : it));
  }, [items, setItems]);

  const handleCommitPointChanges = useCallback(async (itemId: string) => {
    const item = items.find(i => i.id === itemId); if (!item || !item.content) return;
    const points = item.identifiedPoints || [];
    const paired = points.filter(p => p.pairingId);
    if (paired.length > 0) { handleGenerate(itemId, `[ACTION:TRANSPLANT] Precise design transplant.`); return; }
    const modified = points.filter(p => p.modifiedDescription || p.isRemoving);
    if (modified.length > 0) {
      const instr = modified.map(p => p.isRemoving ? `Remove ${p.label}` : `Change ${p.label} to ${p.modifiedDescription}`).join('\n');
      handleGenerate(itemId, instr, { artisticLevel: 80 });
    }
  }, [items, handleGenerate]);

  const handleAutoAlignPoints = useCallback(async (sourceId: string, targetId: string) => {
    const sourceItem = items.find(i => i.id === sourceId);
    const targetItem = items.find(i => i.id === targetId);
    if (!sourceItem?.content || !targetItem?.content) return;
    try {
      const alignment = await autoAlignPoints(sourceItem.content, sourceItem.identifiedPoints || [], targetItem.content, targetItem.identifiedPoints || []);
      setItems(prev => prev.map(it => { if (it.id === targetId) { const nextPoints = it.identifiedPoints?.map(p => { const match = alignment.find(a => a.targetId === p.id); return match ? { ...p, pairingId: match.sourceId, pairingSourceItemId: sourceId } : p; }); return { ...it, identifiedPoints: nextPoints }; } return it; }));
    } catch (e) { console.error(e); }
  }, [items, setItems]);

  const handleFloatingAction = async (id: string, action: string) => {
    const firstItem = items.find(i => selection.includes(i.id)); if (!firstItem) return;
    if (action.startsWith('expr:')) { handleGenerate(firstItem.id, `Change to ${action.split(':')[1]}`); return; }
    if (action.startsWith('inference:')) { handleGenerate(firstItem.id, `inference:${action.split(':')[1]}`); return; }
    if (action.startsWith('evolve_with_level:')) { handleGenerate(firstItem.id, `__EVOLUTION__|${action.split(':')[1]}${isCncMode ? '|CNC' : ''}`); return; }

    if (action.startsWith('model_cmd:')) {
        const fullCmd = action.split(':')[1].trim();
        const result = await parseModelSemanticCommand(fullCmd, firstItem.partList || []);
        const updates: any = {};
        if (result.action === 'paint') updates.partCMFMap = { ...firstItem.partCMFMap, ...result.params };
        setItems(prev => prev.map(it => it.id === firstItem.id ? { ...it, ...updates } : it));
        return;
    }

    switch(action) {
      case 'redo': handleGenerate(firstItem.id, firstItem.prompt); break;
      case 'extract_recipe': 
          const logic = await extractDesignRecipe(items.filter(it => selection.includes(it.id)).map(it => it.content), 0); 
          setRecipePanelData({ images: items.filter(it => selection.includes(it.id)).map(it => it.content), instruction: logic });
          break;
      case 'evolve': handleGenerate(firstItem.id, `__EVOLUTION__|${currentEvolutionLevel}${isCncMode ? '|CNC' : ''}`); break;
      case 'expression': setExpressionState({ itemId: firstItem.id, isOpen: true }); break;
      case 'inference': setInferenceState({ itemId: firstItem.id, isOpen: true }); break;
      case 'variation': handleGenerate(firstItem.id, '[ACTION: VARIATION]'); break;
      case 'remove_bg': handleGenerate(firstItem.id, 'Remove background'); break;
      case 'upscale': handleGenerate(firstItem.id, 'UPSCALE TO 4K', { resolution: '4K', usePro: true }); break;
      case 'edit': setEditMode(true); setIsPropertiesPanelOpen(true); break;
      case 'delete': handleDeleteItems(selection); break;
      case 'copy': handleCopy(firstItem.id); break;
      case 'download': handleDownloadAsset(firstItem.id); break;
      case 'part_knolling': 
          const snapshot = (document.querySelector(`[data-item-id="${firstItem.id}"] canvas`) as HTMLCanvasElement)?.toDataURL();
          handleGenerate(firstItem.id, "Knolling view", { ratio: '16:9' }, snapshot ? [snapshot] : []);
          break;
    }
  };

  return (
    <div 
      className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative"
      onDragOver={(e) => e.preventDefault()}
      onDrop={(e) => { e.preventDefault(); Array.from(e.dataTransfer.files).forEach(f => handleFile(f)); }}
    >
      {/* 修复：补全 TopBar 属性调用 */}
      <TopBar onExport={handleExportProject} onImport={handleImportProject} onCloudExport={handleCloudSave} onCloudImport={handleCloudLoad} onNewProject={() => { resetHistory([]); setView({ x: 0, y: 0, scale: 1 }); setSelection([]); }} />
      {/* 修复：补全 LeftToolbar 属性调用 */}
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => addItem({ id: crypto.randomUUID(), type: ItemType.FRAME, x: 0, y: 0, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' })} recordingStatus={recordingStatus} onStartRecording={startRecording} onStopRecording={stopRecording} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={recordingTime} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection.length > 0 ? selection[0] : null} onSelectItem={(id) => { setSelection([id]); const item = items.find(i => i.id === id); if (item) centerOnItem(item); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => resetHistory(snap.items)} />
      {/* 修复：补全 Canvas 属性调用 */}
      <Canvas 
        ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={addItem} updateItem={handleUpdateItem} updateItems={handleUpdateItems} 
        onContextMenu={(e, id) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId: id || selection[0] })} 
        onDelete={id => handleDeleteItems([id])} editMode={editMode} editTool={editTool} brushSize={brushSize} brushColor={brushColor} segments={segments} onApplyEdit={handleApplyEdit} 
        onSelectItem={(id) => setQuickLookItem(items.find(it => it.id === id) || null)} onPointPicked={handlePickPoint} isPickingPoint={isPickingPoint} onPointTagClick={(it, pt) => chatRef.current?.addPointReference(it.id, it.content, pt.label, [pt.y, pt.x])} 
        onPointRemoved={(it, pt) => chatRef.current?.requestObjectRemoval(it.id, it.content, pt.label, [pt.y, pt.x])} showPointLabels={showPointLabels} onDeletePointLocal={(iid, pid) => setItems(items.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it))} 
        onMovePoint={(iid, pid, ny, nx) => handleUpdateItem(iid, { identifiedPoints: items.find(i => i.id === iid)?.identifiedPoints?.map(p => p.id === pid ? { ...p, y: ny, x: nx } : p) })} onMovePointEnd={(iid, pid, from, to) => chatRef.current?.appendMovementDescription(iid, items.find(i => i.id === iid)?.content || '', items.find(i => i.id === iid)?.identifiedPoints?.find(p => p.id === pid)?.label || '', from, to)} 
        showGrid={showGrid} onZoomToFit={zoomToFit} onCaptureRegion={handleCaptureRegion} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} currentEvolutionLevel={currentEvolutionLevel} captureState={captureState} onExitToolMode={() => setTool('select')} activePartId={activePartId} onPartSelect={setActivePartId} onCameraChange={onCameraChange} onLoadParts={onLoadParts}
