            } else { 
                url = await generateImage(task.prompt, styleObj.promptSuffix, ratioToUse, settings?.artisticLevel || 50, settings?.resolution || '1K', settings?.spatialConfig, "", usePro); 
            }
            setItems(prev => prev.map(i => i.id === task.nid ? { ...i, content: url, status: 'generated' } : i));
        } catch (e: any) { setItems(prev => prev.map(i => i.id === task.nid ? { ...i, status: 'error' } : i)); }
    });
  };

  const handleFrameAction = useCallback(async (frameId: string, action: 'merge' | 'expand' | 'crop' | 'explode', options?: any) => {
    const frame = items.find(i => i.id === frameId);
    if (!frame || frame.type !== ItemType.FRAME) return;

    const children = items.filter(it => 
        it.id !== frame.id && it.type === ItemType.IMAGE && it.content &&
        (it.x + it.width/2) >= frame.x && (it.x + it.width/2) <= frame.x + frame.width && 
        (it.y + it.height/2) >= frame.y && (it.y + it.height/2) <= frame.y + frame.height
    );

    if (action === 'explode') {
        if (children.length === 0) { alert("请在画框内放置至少一张图像执行分离。"); return; }
        const mainImg = children[0];
        setIsAnalyzingJSON(true);
        try {
            const result = await detectImageJSONSegments(mainImg.content, options?.deep === true);
            if (!result.segments || result.segments.length === 0) throw new Error("无法识别");

            const subjectSegments = result.segments.filter((s: any) => s.type === 'subject');
            const combinedMask = createCombinedMask(subjectSegments.map((s: any) => s.box_2d));

            // 生成底图
            const backgroundUrl = await inpaintBackground(mainImg.content, combinedMask, mainImg.aspectRatio || '1:1');
            const parentId = crypto.randomUUID();
            const parentItem: CanvasItem = { ...mainImg, id: parentId, content: backgroundUrl, status: 'generated', prompt: 'Clean Background' };

            let currentItems = [...items.filter(it => it.id !== mainImg.id), parentItem];
            setItems(currentItems);
            setSelection([parentId]);

            // 异步处理透明零件
            subjectSegments.forEach(async (seg: any) => {
                const [ymin, xmin, ymax, xmax] = seg.box_2d;
                // 计算准确的物理宽度和高度，确保和原图完美对应
                const pWidth = (xmax - xmin) / 1000 * mainImg.width;
                const pHeight = (ymax - ymin) / 1000 * mainImg.height;
                const pX = mainImg.x + (xmin / 1000 * mainImg.width);
                const pY = mainImg.y + (ymin / 1000 * mainImg.height);

                const subNid = crypto.randomUUID();
                setItems(prev => [...prev, {
                    id: subNid, type: ItemType.IMAGE, x: pX, y: pY, width: pWidth, height: pHeight,
                    rotation: mainImg.rotation, content: '', status: 'loading', parentId: parentId, isChild: true, isTransparent: true, prompt: seg.label
                }]);

                try {
                    const rawCrop = await cropImageSegment(mainImg.content, seg.box_2d);
                    const transparentUrl = await removeBackground(rawCrop, '1:1');
                    setItems(prev => prev.map(it => it.id === subNid ? { ...it, content: transparentUrl, status: 'generated' } : it));
                } catch (e) {
                    setItems(prev => prev.map(it => it.id === subNid ? { ...it, status: 'error' } : it));
                }
            });
        } catch (e) { alert("解构失败"); } finally { setIsAnalyzingJSON(false); }
    } else if (action === 'merge') {
        if (children.length === 0) return;
        const refs = children.map(c => ({ label: 'Sub', base64: c.content }));
        const nid = crypto.randomUUID();
        const placeholder: CanvasItem = { id: nid, type: ItemType.IMAGE, x: frame.x, y: frame.y, width: frame.width, height: frame.height, rotation: 0, content: '', status: 'loading', prompt: frame.prompt || "Merge", aspectRatio: getClosestAspectRatio(frame.width, frame.height) };
        setItems([...items, placeholder]);
        try {
            const url = await generateWithReferences(placeholder.prompt!, refs, placeholder.aspectRatio!, STYLES[1].promptSuffix, 0.8, '1K');
            setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated' } : i));
        } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
    } else if (action === 'expand') {
        if (children.length === 0) return;
        handleGenerate(children[0].id, "Expand seamlessly", { ratio: getClosestAspectRatio(frame.width, frame.height) });
    } else if (action === 'crop') {
        if (children.length === 0) return;
        const nextItems = items.map(it => it.id === children[0].id ? { ...it, x: frame.x, y: frame.y, width: frame.width, height: frame.height } : it).filter(it => it.id !== frame.id);
        setItems(nextItems); commit(nextItems); setSelection([children[0].id]);
    }
  }, [items, commit, handleGenerate, setItems]);

  const handleExportProject = useCallback(() => {
