const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const VALID_ASPECT_RATIOS = ['1:1', '3:4', '4:3', '9:16', '16:9'];

/**
 * 清洗透明通道，去除 AI 生成的半透明边缘噪点
 */
const cleanAlphaChannel = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d')!;
            ctx.drawImage(img, 0, 0);

            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;

            for (let i = 0; i < data.length; i += 4) {
                const alpha = data[i + 3];
                // 阈值处理：如果 alpha 值较小（可能是马赛克噪点），设为全透明
                if (alpha < 40) {
                    data[i + 3] = 0;
                } else if (alpha > 220) {
                    data[i + 3] = 255;
                }
            }

            ctx.putImageData(imageData, 0, 0);
            resolve(canvas.toDataURL('image/png'));
        };
        img.src = base64;
    });
};

/**
 * 将位图转换为 SVG 矢量路径
 */
export const vectorizeImage = async (base64: string): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            try {
                // @ts-ignore - ImageTracer is globally loaded via script tag
                const svgString = ImageTracer.imageToSVG(img, { 
                    ltres: 0.1, 
                    qtres: 0.1, 
                    strokewidth: 0.5,
                    numberofcolors: 32,
                    pathomit: 8,
                    blurradius: 0.2,
                    blurdelta: 10
                });
                const encoded = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgString)));
                resolve(encoded);
            } catch (e) {
                reject(e);
            }
        };
        img.src = base64;
    });
};

const normalizeAspectRatio = (ratio?: string): string => {
  if (!ratio) return '1:1';
  if (VALID_ASPECT_RATIOS.includes(ratio)) return ratio;
  try {
    const [w, h] = ratio.split(':').map(Number);
    if (isNaN(w) || isNaN(h)) return '1:1';
    const numericRatio = w / h;
    const targets = [{ id: '1:1', val: 1 }, { id: '4:3', val: 4/3 }, { id: '3:4', val: 3/4 }, { id: '16:9', val: 16/9 }, { id: '9:16', val: 9/16 }];
    return targets.reduce((prev, curr) => Math.abs(curr.val - numericRatio) < Math.abs(prev.val - numericRatio) ? curr : prev).id;
  } catch (e) { return '1:1'; }
};

export const getClosestGeminiRatio = (width: number, height: number): string => {
    const ratio = width / height;
    const targets = [{ id: '1:1', val: 1 }, { id: '4:3', val: 4/3 }, { id: '3:4', val: 3/4 }, { id: '16:9', val: 16/9 }, { id: '9:16', val: 9/16 }];
    return targets.reduce((prev, curr) => Math.abs(curr.val - ratio) < Math.abs(prev.val - ratio) ? curr : prev).id;
};

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

async function retryWithBackoff<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try { return await operation(); } catch (error: any) {
    let errorStr = (typeof error === 'string' ? error : error.message || JSON.stringify(error)).toLowerCase();
    if (isRetryableError(errorStr) && retries > 0) { await sleep(delay); return retryWithBackoff(operation, retries - 1, delay * 2); }
    throw error;
  }
}

const isRetryableError = (s: string) => s.includes('overloaded') || s.includes('unavailable') || s.includes('429') || s.includes('500') || s.includes('503');

export const removeBackground = async (base64: string, ratio: string): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: "Remove background. MAINTAIN SUBJECT GEOMETRY 100%. Output high-quality transparent PNG. Zero artifacts." }
                ]
            }],
            config: { imageConfig: { aspectRatio: normalizeAspectRatio(ratio) as any } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) {
            const rawTransparent = `data:image/png;base64,${part.inlineData.data}`;
            return await cleanAlphaChannel(rawTransparent);
        }
        throw new Error("BG Removal failed.");
    });
};

export const inpaintBackground = async (sourceBase64: string, maskBase64: string, ratio: string): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const srcData = sourceBase64.split(',')[1] || sourceBase64;
        const maskData = maskBase64.split(',')[1] || maskBase64;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{
                parts: [
                    { inlineData: { data: srcData, mimeType: 'image/jpeg' } },
                    { inlineData: { data: maskData, mimeType: 'image/png' } },
                    { text: "Inpaint the masked areas. Remove the objects in the mask and fill the area naturally with background textures and lighting. Seamless integration." }
                ]
            }],
            config: { imageConfig: { aspectRatio: normalizeAspectRatio(ratio) as any } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) return `data:image/jpeg;base64,${part.inlineData.data}`;
        throw new Error("Inpainting failed.");
    });
};

export const detectImageJSONSegments = async (base64: string, deep: boolean = false): Promise<any> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const prompt = deep 
            ? "深入识别并分析图像中核心主体的工业构成零件。识别如：按键、屏幕、支架、外壳、光学镜头等。"
            : "识别并分析图像中的设计构成要素。区分主体（Subject）和背景（Background）。";

        const response = await ai.models.generateContent({ 
            model: 'gemini-3-flash-preview', 
            contents: [{ 
                parts: [
                    { inlineData: { data: base64.split(',')[1] || base64, mimeType: 'image/jpeg' } }, 
                    { text: `${prompt} 返回 JSON。每个 segment 包含 label, type (subject|background), box_2d [ymin, xmin, ymax, xmax]。` }
                ] 
            }], 
            config: { 
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        segments: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    label: { type: Type.STRING },
                                    type: { type: Type.STRING },
                                    box_2d: { type: Type.ARRAY, items: { type: Type.NUMBER } }
                                },
                                required: ["label", "type", "box_2d"]
                            }
                        }
                    },
                    required: ["segments"]
                }
            } 
        });
        return JSON.parse(response.text);
    });
};

export const chatWithGemini = async (prompt: string, history: { role: 'user' | 'model', parts: any[] }[] = [], useThinking: boolean = false, attachments: string[] = [], useSearch: boolean = false): Promise<string> => {
  return retryWithBackoff(async () => {
    const ai = getAI(); const model = useThinking ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const config: any = { systemInstruction: "You are a professional visual designer." };
    if (useThinking) config.thinkingConfig = { thinkingBudget: 16384 }; if (useSearch) config.tools = [{ googleSearch: {} }];
    const currentParts: any[] = attachments.map(base64 => ({ inlineData: { data: base64.split(',')[1] || base64, mimeType: base64.split(';')[0].split(':')[1] || 'image/jpeg' } }));
    currentParts.push({ text: prompt });
    const response = await ai.models.generateContent({ model, contents: [...history, { role: 'user', parts: currentParts }], config });
    return response.text || "No response.";
  });
};

export const generateImage = async (prompt: string, styleSuffix: string, ratio: string, artisticScale: number = 50, resolution: string = '1K', spatial?: SpatialConfig, recipeInstruction?: string, usePro: boolean = false): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
        const config: any = { imageConfig: { aspectRatio: normalizeAspectRatio(ratio) as any }, temperature: artisticScale / 50.0 };
        if (usePro) config.imageConfig.imageSize = resolution;
        const response = await ai.models.generateContent({ model, contents: [{ parts: [{ text: `${prompt}. ${recipeInstruction || ''}. Style: ${styleSuffix}.` }] }], config });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); if (part?.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
        throw new Error("Image failed.");
