  }, [selection, undo, redo]);

  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item)), [setItems]);
  const handleUpdateItems = useCallback((updates: { id: string, updates: Partial<CanvasItem> }[]) => setItems(prev => { 
    const newItems = [...prev]; 
    updates.forEach(({ id, updates: itemUpdates }) => { 
        const idx = newItems.findIndex(i => i.id === id); 
        if (idx !== -1) {
            const oldItem = newItems[idx];
            newItems[idx] = { ...oldItem, ...itemUpdates }; 

            if (itemUpdates.x !== undefined || itemUpdates.y !== undefined) {
                const dx = (itemUpdates.x ?? oldItem.x) - oldItem.x;
                const dy = (itemUpdates.y ?? oldItem.y) - oldItem.y;
                if (dx !== 0 || dy !== 0) {
                    prev.forEach((child, cIdx) => {
                        if (child.parentId === id) {
                            newItems[cIdx] = { ...child, x: child.x + dx, y: child.y + dy };
                        }
                    });
                }
            }
        }
    }); 
    return newItems; 
  }), [setItems]);

