      />
      {(isCapturing || isAnalyzingJSON) && ( <div className="fixed inset-0 z-[3000] pointer-events-none flex items-center justify-center"> <div className="bg-black/40 backdrop-blur-md px-10 py-6 rounded-[28px] border border-white/10 shadow-3xl flex flex-col items-center gap-4 animate-in zoom-in-95"> <RefreshIcon className="w-8 h-8 text-indigo-400 animate-spin" /> <span className="text-[12px] font-black text-white uppercase tracking-[0.3em]">{isAnalyzingJSON ? '处理中...' : '处理中...'}</span> </div> </div> )}
