tionLevel={currentEvolutionLevel} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onUpdatePoint={handleUpdatePoint} onClearAllPoints={() => {}} onCommitPointChanges={() => {}} onAutoAlign={async (s, t) => {}} onClosePanel={() => setIsPropertiesPanelOpen(false)} onFloatingAction={handleFloatingAction} /> </div> </div> </div>
