        setItems(next); commit(next); setSelection([newItem.id]);
    }
  }, [selection, items, commit, setItems]);

  const handleGenerate = async (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>) => {
    const item = items.find(i => i.id === id);
    const rawPrompt = overridePrompt || item?.prompt || "Professional design";
    const { tasks, isEvolution, level } = parseGenerationIntent(rawPrompt, item || null, settings);
    if (isEvolution && level !== undefined) setCurrentEvolutionLevel(level);

    const usePro = settings?.usePro || false;
    const ratio = settings?.ratio || item?.aspectRatio || '1:1';
    const styleObj = STYLES.find(s => s.id === (settings?.style || 'industrial')) || STYLES[1];

    let currentTemp = [...items];
    tasks.forEach((t) => {
        const spot = findPlacementSpot(item?.width || 512, item?.height || 512, currentTemp, item || undefined);
        const placeholder: CanvasItem = { id: t.nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: item?.width || 512, height: item?.height || 512, rotation: item?.rotation || 0, content: '', status: 'loading', prompt: t.prompt, aspectRatio: ratio };
        currentTemp.push(placeholder);
    });
    setItems(currentTemp); commit(currentTemp); setSelection(tasks.map(t => t.nid));

    tasks.forEach(async (task) => {
        try {
            let url: string;
            if (task.prompt === '[ACTION: VARIATION]' && item?.content) {
                url = await generateTopologyVariation(item.content, ratio, styleObj.promptSuffix, usePro);
            } else if (item?.content) {
                url = await generateWithReferences(task.prompt, [{ label: 'Source', base64: item.content }], ratio, styleObj.promptSuffix, settings?.artisticLevel || 50, '1K', settings?.spatialConfig, '', undefined, usePro);
            } else {
                url = await generateImage(task.prompt, styleObj.promptSuffix, ratio, settings?.artisticLevel || 50, '1K', settings?.spatialConfig, '', usePro);
            }
            setItems(prev => prev.map(i => i.id === task.nid ? { ...i, content: url, status: 'generated' } : i));
        } catch (e) { setItems(prev => prev.map(i => i.id === task.nid ? { ...i, status: 'error' } : i)); }
    });
  };

  const handleFrameAction = useCallback(async (frameId: string, action: 'merge' | 'expand' | 'crop' | 'explode', options?: any) => {
    const frame = items.find(i => i.id === frameId);
    if (!frame) return;
    const children = items.filter(it => 
        it.id !== frame.id && it.type === ItemType.IMAGE && it.content &&
        (it.x + it.width/2) >= frame.x && (it.x + it.width/2) <= frame.x + frame.width && 
        (it.y + it.height/2) >= frame.y && (it.y + it.height/2) <= frame.y + frame.height
    );

    if (action === 'explode') {
        if (children.length === 0) { alert("请在画框内置入图像"); return; }
        const mainImg = children[0];
        setIsAnalyzingJSON(true);
        try {
            const result = await detectImageJSONSegments(mainImg.content, options?.deep);
            const subjects = result.segments.filter((s: any) => s.type === 'subject');
            const mask = createCombinedMask(subjects.map((s: any) => s.box_2d));
            const bgUrl = await inpaintBackground(mainImg.content, mask, mainImg.aspectRatio || '1:1');

            const parentId = crypto.randomUUID();
            const parentItem: CanvasItem = { ...mainImg, id: parentId, content: bgUrl, status: 'generated', prompt: 'Background' };
            let nextItems = [...items.filter(it => it.id !== mainImg.id), parentItem];
            setItems(nextItems); setSelection([parentId]);

            subjects.forEach(async (seg: any) => {
                const [ymin, xmin, ymax, xmax] = seg.box_2d;
                // 对齐校准：计算真实的画布坐标
                const pW = ((xmax - xmin) / 1000) * mainImg.width;
                const pH = ((ymax - ymin) / 1000) * mainImg.height;
                const pX = mainImg.x + (xmin / 1000) * mainImg.width;
                const pY = mainImg.y + (ymin / 1000) * mainImg.height;
                const sid = crypto.randomUUID();
                setItems(prev => [...prev, { id: sid, type: ItemType.IMAGE, x: pX, y: pY, width: pW, height: pH, rotation: mainImg.rotation, content: '', status: 'loading', parentId, isChild: true, isTransparent: true, prompt: seg.label }]);
                try {
                    const crop = await cropImageSegment(mainImg.content, seg.box_2d);
                    const cutout = await removeBackground(crop, '1:1');
                    setItems(prev => prev.map(i => i.id === sid ? { ...i, content: cutout, status: 'generated' } : i));
                } catch (e) { setItems(prev => prev.map(i => i.id === sid ? { ...i, status: 'error' } : i)); }
            });
        } catch (e) { alert("分离失败"); } finally { setIsAnalyzingJSON(false); }
    } else if (action === 'merge' && children.length > 0) {
        const refs = children.map(c => ({ label: 'Ref', base64: c.content }));
        handleGenerate(frame.id, frame.prompt || "Seamless Merge", { ratio: getClosestAspectRatio(frame.width, frame.height) });
    }
  }, [items, commit, setItems]);

  const handleVectorize = async (id: string) => {
    const it = items.find(i => i.id === id);
    if (!it || !it.content) return;
    setIsAnalyzingJSON(true);
    try {
        const svg = await vectorizeImage(it.content);
        handleUpdateItem(id, { content: svg, prompt: (it.prompt || "") + " (Vectorized)" });
    } catch (e) { alert("矢量化失败"); } finally { setIsAnalyzingJSON(false); }
  };

  const handleFloatingAction = (id: string, action: string) => {
    const item = items.find(i => i.id === id) || (selection.length > 0 ? items.find(i => i.id === selection[0]) : null);
    if (!item) return;
    if (action === 'vectorize') { handleVectorize(item.id); return; }
    if (action === 'copy') { handleCopy(item.id); return; }
    if (action === 'delete') { handleDeleteItems(selection); return; }
    if (action === 'remove_bg') { handleGenerate(item.id, "Remove background"); return; }
    if (action === 'variation') { handleGenerate(item.id, "[ACTION: VARIATION]"); return; }
    if (action === 'edit') { setEditMode(true); setIsPropertiesPanelOpen(true); return; }
    if (action === 'expression') { setExpressionState({ itemId: item.id, isOpen: true }); return; }
    if (action === 'inference') { setInferenceState({ itemId: item.id, isOpen: true }); return; }
    if (action === 'evolve') { handleGenerate(item.id, `__EVOLUTION__|${currentEvolutionLevel}`); return; }
  };

  const handleExportProject = () => {
    const pkg: ProjectPackage = { version: '1.0', timestamp: Date.now(), items, view };
    const blob = new Blob([JSON.stringify(pkg)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `project_${Date.now()}.json`; a.click();
  };

  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const pkg = JSON.parse(e.target?.result as string) as ProjectPackage;
            setItems(pkg.items); setView(pkg.view || { x: 0, y: 0, scale: 1 }); resetHistory(pkg.items);
        } catch (err) { alert("导入失败"); }
    };
    reader.readAsText(file);
  };

  const addItem = (it: CanvasItem) => { const next = [...items, it]; setItems(next); commit(next); };

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative" onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); Array.from(e.dataTransfer.files).forEach(f => handleFile(f)); }}>
      <TopBar onExport={handleExportProject} onImport={handleImportProject} onCloudExport={async () => { await uploadProjectToCloud({ version: '1.0', timestamp: Date.now(), items, view }); }} onCloudImport={async () => { const p = await downloadProjectFromCloud(); setItems(p.items); setView(p.view); resetHistory(p.items); }} onNewProject={() => { resetHistory([]); setView({ x: 0, y: 0, scale: 1 }); setSelection([]); }} />
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => addItem({ id: crypto.randomUUID(), type: ItemType.FRAME, x: (window.innerWidth/2 - view.x)/view.scale - 400, y: (window.innerHeight/2 - view.y)/view.scale - 300, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' })} recordingStatus={recordingStatus} onStartRecording={async () => {}} onStopRecording={() => {}} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={0} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection[0]} onSelectItem={id => { setSelection([id]); const it = items.find(i => i.id === id); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={snap => resetHistory(snap.items)} />
      <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={addItem} updateItem={handleUpdateItem} updateItems={handleUpdateItems} onDelete={id => handleDeleteItems([id])} editMode={editMode} editTool={editTool} brushSize={brushSize} brushColor={brushColor} segments={segments} onSelectItem={id => setQuickLookItem(items.find(i => i.id === id) || null)} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} captureState={captureState} onExitToolMode={() => setTool('select')} />
      <div className={`fixed right-4 top-4 bottom-4 flex flex-col items-end transition-all duration-500 z-40 ${isPropertiesPanelOpen ? 'w-80' : 'w-16'}`}>
        {!isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(true)} className="w-14 h-14 rounded-full flex items-center justify-center bg-[#09090b] border border-zinc-800 text-indigo-400 shadow-2xl hover:scale-110"><SlidersIcon className="w-6 h-6"/></button>}
        <div className={`flex-1 w-full overflow-hidden transition-all duration-500 origin-right ${isPropertiesPanelOpen ? 'scale-100 opacity-100' : 'scale-90 opacity-0 pointer-events-none'}`}>
            <PropertiesPanel selectedItem={selectedItem} selectedItems={selectedItems} onUpdateItem={handleUpdateItem} onGenerate={handleGenerate} onDelete={id => handleDeleteItems([id])} onAutoPrompt={async id => { const p = await analyzeImageForPrompt(items.find(i => i.id === id)?.content || ""); handleUpdateItem(id, { prompt: p }); }} onFrameAction={handleFrameAction} onEnterEditMode={() => setEditMode(true)} onExitEditMode={() => setEditMode(false)} onFloatingAction={handleFloatingAction} isAnalyzingJSON={isAnalyzingJSON} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onClosePanel={() => setIsPropertiesPanelOpen(false)} />
        </div>
      </div>
      <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[70] pointer-events-none"> <BottomBar lastGenerated={null} externalRef={externalRefImage} onExternalRefConsumed={() => setExternalRefImage(null)} onGenerate={(p,s,r,ref,c,l,res,rec,pro) => handleGenerate('', p, {style:s, ratio:r, imageCount:c, artisticLevel:l, resolution:res, recipeId:rec, usePro:pro})} /> </div>
      {isAnalyzingJSON && <div className="fixed inset-0 z-[3000] bg-black/20 backdrop-blur-sm flex items-center justify-center"> <div className="bg-black/60 p-10 rounded-[32px] border border-white/10 flex flex-col items-center gap-4"> <RefreshIcon className="w-8 h-8 text-indigo-400 animate-spin" /> <span className="text-[12px] font-black text-white uppercase tracking-[0.3em]">AI 处理中...</span> </div> </div>}
      <GeminiChatPanel ref={chatRef} onAddToCanvas={handleAddToCanvas} />
      <input type="file" ref={fileInputRef} onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f); e.target.value=''; }} className="hidden" accept="image/*" />
    </div>
  );
};
export default App;

