import { useRef, useState, useImperativeHandle, forwardRef, useMemo, useEffect, useCallback } from 'react';
import React from 'react';
import { CanvasItem, ViewState, Point, ToolType, ItemType, EditToolType, Segment, IdentifiedPoint, Rect, ExpressionState, SpatialConfig } from '../types';
import { RotateCcwIcon, SparklesIcon, XIcon, TrashIcon, CameraIcon, PenIcon, BoxIcon, LinkIcon, MessageCircleIcon, LanguagesIcon, ArrowIcon, SquareIcon, CircleIcon, BrushIcon, ScanIcon, RefreshIcon } from './Icons';
import MaskCanvas, { MaskCanvasRef } from './MaskCanvas';
import FloatingSelectionBar from './FloatingSelectionBar';
import ExpressionController from './ExpressionController';
import VolumeInferencePanel from './VolumeInferencePanel';
import AntigravityLoading from './AntigravityLoading';
import { useCanvasMath } from '../hooks/useCanvasMath';
import { useTransformEngine } from '../hooks/useTransformEngine';
import { useAnnotations, Annotation } from '../hooks/useAnnotations';
import { useCaptureManager } from '../hooks/useCaptureManager';

interface CanvasProps {
  items: CanvasItem[];
  selection: string[];
  tool: ToolType;
  view: ViewState;
  setView: (view: ViewState | ((prev: ViewState) => ViewState)) => void;
  setSelection: (ids: string[]) => void;
  addItem: (item: CanvasItem) => void;
  updateItem: (id: string, updates: Partial<CanvasItem>) => void;
  updateItems?: (updates: { id: string, updates: Partial<CanvasItem> }[]) => void;
  onContextMenu?: (e: React.MouseEvent, itemId?: string) => void;
  onDelete?: (id: string) => void;
  editMode?: boolean;
  editTool?: EditToolType;
  brushSize?: number;
  brushColor?: string;
  segments?: Segment[];
  onSelectItem?: (id: string) => void;
  onFloatingAction?: (id: string, action: string) => void;
  expressionState: ExpressionState;
  setExpressionState: (state: ExpressionState) => void;
  inferenceState: { itemId: string, isOpen: boolean };
  setInferenceState: (state: { itemId: string, isOpen: boolean }) => void;
  captureState?: ReturnType<typeof useCaptureManager>;
  onExitToolMode?: () => void;
}

export interface CanvasRef { 
    getMaskData: () => Promise<{ cutout: string, mask: string } | null>;
    clearMask: () => void;
}

const Canvas = forwardRef<CanvasRef, CanvasProps>(({ 
  items, selection, tool, view, setView, setSelection, addItem, updateItem, updateItems,
  onContextMenu, editMode, editTool = 'brush', brushSize = 30, brushColor = '#6366f1',
  onSelectItem, onFloatingAction, expressionState, setExpressionState, inferenceState, setInferenceState,
  captureState, onExitToolMode
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const maskCanvasRef = useRef<MaskCanvasRef>(null);
  const { screenToCanvas, handleScale, handleSize, borderWidth, rotateHandleSize, rotateHandleOffset, rotateIconSize, snapThreshold } = useCanvasMath(view, containerRef);
  const { transforming, snapLines, startTransform, updateTransform, endTransform } = useTransformEngine(items, updateItem, snapThreshold);

  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState<Point>({ x: 0, y: 0 });
  const [isMarquee, setIsMarquee] = useState(false);
  const [marqueeStart, setMarqueeStart] = useState<Point>({ x: 0, y: 0 });
  const [marqueeEnd, setMarqueeEnd] = useState<Point>({ x: 0, y: 0 });
  const [mouseCanvasPos, setMouseCanvasPos] = useState<Point>({ x: 0, y: 0 });

  useImperativeHandle(ref, () => ({ 
    getMaskData: async () => { if (!maskCanvasRef.current) return null; const cutout = await maskCanvasRef.current.getMaskedImage(); const mask = await maskCanvasRef.current.getSelectionMask(); return (cutout && mask) ? { cutout, mask } : null; },
    clearMask: () => maskCanvasRef.current?.clearMask()
  }));

  const handleMouseDown = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY);
    if (e.button === 1 || tool === 'hand') { setIsPanning(true); setPanStart({ x: e.clientX - view.x, y: e.clientY - view.y }); return; }
    if (tool === 'select' && (e.target as HTMLElement).id === 'canvas-bg') { 
        setIsMarquee(true); setMarqueeStart(pos); setMarqueeEnd(pos); 
        if (!e.shiftKey) setSelection([]); 
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY); setMouseCanvasPos(pos);
    if (isPanning) setView({ ...view, x: e.clientX - panStart.x, y: e.clientY - panStart.y });
    else if (isMarquee) { 
        setMarqueeEnd(pos); 
        const x1 = Math.min(marqueeStart.x, pos.x), y1 = Math.min(marqueeStart.y, pos.y), x2 = Math.max(marqueeStart.x, pos.x), y2 = Math.max(marqueeStart.y, pos.y);
        setSelection(items.filter(i => i.x >= x1 && i.x + i.width <= x2 && i.y >= y1 && i.y + i.height <= y2).map(i => i.id));
    }
    else if (transforming) updateTransform(pos);
  };

  const handleMouseUp = () => { setIsPanning(false); setIsMarquee(false); endTransform(); };

  const sortedItems = useMemo(() => [...items].sort((a, b) => a.type === ItemType.FRAME ? -1 : 1), [items]);

  const floatingUI = useMemo(() => {
    if (selection.length === 0) return null;
    const sels = items.filter(i => selection.includes(i.id));
    const minX = Math.min(...sels.map(it => it.x)), minY = Math.min(...sels.map(it => it.y));
    const maxX = Math.max(...sels.map(it => it.x + it.width));
    return { x: (minX + (maxX - minX)/2) * view.scale + view.x, y: minY * view.scale + view.y - 40 };
  }, [selection, items, view]);

  return (
    <div ref={containerRef} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} id="canvas-bg" className={`relative w-full h-full overflow-hidden bg-[#f4f4f5] dark:bg-[#09090b] ${tool === 'hand' ? 'cursor-grab' : 'cursor-default'}`}>
      <div className="absolute inset-0 origin-top-left" style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})` }}>
        {sortedItems.map(item => {
          const isSel = selection.includes(item.id);
          return (
            <div key={item.id} className={`absolute ${isSel ? 'z-50' : 'z-10'}`} style={{ left: item.x, top: item.y, width: item.width, height: item.height, transform: `rotate(${item.rotation}deg)` }}>
              <div onMouseDown={e => { e.stopPropagation(); if (tool === 'select') { const ns = e.shiftKey ? [...selection, item.id] : [item.id]; setSelection(ns); startTransform('drag', mouseCanvasPos, ns); } }} className={`w-full h-full relative rounded-xl overflow-hidden border-2 ${isSel ? 'border-indigo-500' : 'border-transparent'} ${item.type === ItemType.FRAME ? 'bg-white/5 border-zinc-800' : ''}`}>
                {item.type === ItemType.IMAGE && it.content && <img src={item.content} className="w-full h-full object-contain pointer-events-none" />}
                {item.type === ItemType.FRAME && <div className="p-2 text-[10px] font-black text-zinc-500 uppercase">{item.content}</div>}
              </div>
              {isSel && !editMode && (
                <>
                  {['top-left', 'top-right', 'bottom-left', 'bottom-right'].map(h => (
                    <div key={h} onMouseDown={e => { e.stopPropagation(); startTransform('resize', mouseCanvasPos, [item.id], h); }} className="absolute w-3 h-3 bg-white border-2 border-indigo-500 rounded-full shadow-lg" style={{ left: h.includes('left') ? 0 : '100%', top: h.includes('top') ? 0 : '100%', transform: 'translate(-50%, -50%)' }} />
                  ))}
                </>
              )}
            </div>
          );
        })}
      </div>
      {floatingUI && !editMode && (
        <div className="absolute pointer-events-none" style={{ left: floatingUI.x, top: floatingUI.y, transform: 'translateX(-50%)' }}>
          <FloatingSelectionBar items={items.filter(i => selection.includes(i.id))} onAction={a => onFloatingAction?.(selection[0], a)} />
        </div>
      )}
      {isMarquee && <div className="absolute border-2 border-indigo-500 bg-indigo-500/10" style={{ left: Math.min(marqueeStart.x, marqueeEnd.x) * view.scale + view.x, top: Math.min(marqueeStart.y, marqueeEnd.y) * view.scale + view.y, width: Math.abs(marqueeStart.x - marqueeEnd.x) * view.scale, height: Math.abs(marqueeStart.y - marqueeEnd.y) * view.scale }} />}
    </div>
  );
});
export default Canvas;

import { GoogleGenAI, Type } from "@google/genai";
import { SpatialConfig, InferenceSettings, PartCMF } from "../types";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
const VALID_ASPECT_RATIOS = ['1:1', '3:4', '4:3', '9:16', '16:9'];

/**
 * 核心：清洗透明通道。去除 AI 在生成透明图层时产生的边缘半透明马赛克噪点。
 */
const cleanAlphaChannel = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d')!;
            ctx.drawImage(img, 0, 0);

            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;

            for (let i = 0; i < data.length; i += 4) {
                const alpha = data[i + 3];
                // 阈值处理：如果 alpha 值较小（马赛克噪点），强制设为全透明；
                // 如果 alpha 值较高，设为全不透明，确保边缘锐利。
                if (alpha < 50) {
                    data[i + 3] = 0;
                } else if (alpha > 220) {
                    data[i + 3] = 255;
                }
            }

            ctx.putImageData(imageData, 0, 0);
            resolve(canvas.toDataURL('image/png'));
        };
        img.src = base64;
    });
};

/**
 * 核心：将位图转换为 SVG 矢量路径。
 */
export const vectorizeImage = async (base64: string): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            try {
                // @ts-ignore - ImageTracer 加载自 index.html 的 script 标签
                const svgString = ImageTracer.imageToSVG(img, { 
                    ltres: 0.1, 
                    qtres: 0.1, 
                    strokewidth: 0.5,
                    numberofcolors: 16,
                    pathomit: 8,
                    blurradius: 0.1,
                    blurdelta: 10
                });
                const encoded = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgString)));
                resolve(encoded);
            } catch (e) {
                reject(e);
            }
        };
        img.src = base64;
    });
};

const normalizeAspectRatio = (ratio?: string): string => {
  if (!ratio) return '1:1';
  if (VALID_ASPECT_RATIOS.includes(ratio)) return ratio;
  const targets = [{ id: '1:1', val: 1 }, { id: '4:3', val: 4/3 }, { id: '3:4', val: 3/4 }, { id: '16:9', val: 16/9 }, { id: '9:16', val: 9/16 }];
  try {
    const [w, h] = ratio.split(':').map(Number);
    const numericRatio = w / h;
    return targets.reduce((prev, curr) => Math.abs(curr.val - numericRatio) < Math.abs(prev.val - numericRatio) ? curr : prev).id;
  } catch (e) { return '1:1'; }
};

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

async function retryWithBackoff<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try { return await operation(); } catch (error: any) {
    if (retries > 0) { await sleep(delay); return retryWithBackoff(operation, retries - 1, delay * 2); }
    throw error;
  }
}

export const removeBackground = async (base64: string, ratio: string): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1];
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType: 'image/png' } },
                    { text: "Remove background. High precision cutout. Maintain original object geometry. Output transparent PNG." }
                ]
            }],
            config: { imageConfig: { aspectRatio: normalizeAspectRatio(ratio) as any } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) {
            const rawPNG = `data:image/png;base64,${part.inlineData.data}`;
            // 获取 AI 返回的图后，立即进行透明通道清洗
            return await cleanAlphaChannel(rawPNG);
        }
        throw new Error("BG Removal failed.");
    });
};

