/**
 * 核心：Gemini 聊天服务
 */
export const chatWithGemini = async (prompt: string, history: any[], think: boolean = false, images: string[] = [], search: boolean = false): Promise<string> => {
    const ai = getAI();
    const contents: any[] = history.map(h => ({
        role: h.role,
        parts: h.parts.map((p: any) => ({ text: p.text }))
    }));

    const parts: any[] = images.map(img => ({ 
        inlineData: { data: img.split(',')[1], mimeType: 'image/jpeg' } 
    }));
    parts.push({ text: prompt });

    contents.push({ role: 'user', parts });

    const config: any = {};
    if (think) {
        config.thinkingConfig = { thinkingBudget: 32768 };
    }
    if (search) {
        config.tools = [{ googleSearch: {} }];
    }

    const response = await ai.models.generateContent({
        model: think ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
        contents,
        config
    });

    return response.text || "";
};

/**
 * 获取最接近的 Gemini 支持的比例
 */
export const getClosestGeminiRatio = (width: number, height: number): string => {
  const ratio = width / height;
  const targets = [
    { id: '1:1', val: 1 },
    { id: '4:3', val: 4/3 },
    { id: '3:4', val: 3/4 },
    { id: '16:9', val: 16/9 },
    { id: '9:16', val: 9/16 }
  ];
  return targets.reduce((prev, curr) => 
    Math.abs(curr.val - ratio) < Math.abs(prev.val - ratio) ? curr : prev
  ).id;
};

