 * 核心：Veo 视频生成任务
 * 支持文本及可选的参考图像
 */
export const generateVideo = async (prompt: string, imageBase64?: string): Promise<string> => {
    return retryWithBackoff(async () => {
        // 1. 按照规范：必须检查并引导 API Key 选择
        if (typeof window.aistudio !== 'undefined') {
            const hasKey = await window.aistudio.hasSelectedApiKey();
            if (!hasKey) {
                await window.aistudio.openSelectKey();
                // 按照规范：竞态处理，触发后立即假定成功并继续
            }
        }

        const ai = getAI();
        const config: any = {
            numberOfVideos: 1,
            resolution: '720p',
            aspectRatio: '16:9'
        };

        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt: prompt || "A cinematic motion sweep of the design object",
            image: imageBase64 ? {
                imageBytes: imageBase64.split(',')[1] || imageBase64,
                mimeType: imageBase64.split(';')[0].split(':')[1] || 'image/jpeg'
            } : undefined,
            config
        });

        // 2. 轮询任务状态
        while (!operation.done) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            operation = await ai.operations.getVideosOperation({ operation: operation });
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (!downloadLink) throw new Error("Video generation failed: No URI returned.");

        // 3. 按照规范：拼接 API Key 以便加载
        return `${downloadLink}&key=${process.env.API_KEY}`;
    });
};

/**
 * 核心：Gemini 聊天服务 (支持 Thinking 模式)
 */
export const chatWithGemini = async (prompt: string, history: { role: 'user' | 'model', parts: any[] }[] = [], useThinking: boolean = false, attachments: string[] = [], useSearch: boolean = false): Promise<string> => {
  return retryWithBackoff(async () => {
    const ai = getAI();
    // Thinking 模式必须使用 gemini-3-pro-preview
    const model = useThinking ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const config: any = { 
        systemInstruction: "You are a professional visual designer and industrial engineer." 
    };

    if (useThinking) {
        // 按照规范：ThinkingBudget 设为 32768，且不设置 maxOutputTokens
        config.thinkingConfig = { thinkingBudget: 32768 };
    }

    if (useSearch) {
        config.tools = [{ googleSearch: {} }];
    }

    const currentParts: any[] = attachments.map(base64 => ({ 
        inlineData: { 
            data: base64.split(',')[1] || base64, 
            mimeType: base64.split(';')[0].split(':')[1] || 'image/jpeg' 
        } 
    }));
    currentParts.push({ text: prompt });

    const response = await ai.models.generateContent({ 
        model, 
        contents: [...history, { role: 'user', parts: currentParts }], 
        config 
    });
    return response.text || "No response.";
  });
};

