      const a = document.createElement('a'); a.href = url; a.download = `${activeSession.title}.json`; a.click();
    } else if (format === 'md') {
      const md = messages.map(m => `### ${m.role === 'user' ? '用户提问' : 'Gemini 回答'}\n\n${m.text}\n\n---\n`).join('\n');
