        const imageToAnimate = currentAttachments.length > 0 ? currentAttachments[0].original : undefined;
        const videoUrl = await generateVideo(textToSend || "Professional visual motion analysis", imageToAnimate);
        resultMsg = { id: crypto.randomUUID(), role: 'model', text: "Veo 3.1 视频生成成功。", videoUrl, context: contextForRedo };
      } else if (toolType === 'image') {
        const styleSuffix = STYLES[1].promptSuffix;
        let url: string;
        const maskedAttachment = currentAttachments.find(a => a.maskData);
        if (maskedAttachment) {
            const ratio = await detectAspectRatio(maskedAttachment.original);
            url = await editImage(maskedAttachment.original, textToSend, ratio, maskedAttachment.maskData);
        } else if (currentAttachments.length > 0) {
            const refs = currentAttachments.map((a, i) => ({ label: `Ref ${i+1}`, base64: a.original }));
            const ratio = await detectAspectRatio(currentAttachments[0].original);
            url = await generateWithReferences(textToSend, refs, ratio, styleSuffix, 0.8, '1K');
        } else {
            url = await generateImage(textToSend, styleSuffix, '1:1', 1.0, '1K');
        }
        resultMsg = { id: crypto.randomUUID(), role: 'model', text: "已完成视觉重构。预览如下：", images: [url], context: contextForRedo };
      } else if (toolType === 'json_analysis' && currentAttachments.length > 0) {
        const result = await detectImageJSONSegments(currentAttachments[0].original);
        if (onReceiveSegments) onReceiveSegments(result.segments || []);
        resultMsg = { id: crypto.randomUUID(), role: 'model', text: `已完成工业语义拆解。\n\`\`\`json\n${JSON.stringify(result, null, 2)}\n\`\`\``, isJson: true, context: contextForRedo };
      } else {
        const aiImages = currentAttachments.map(a => a.original);
        // 使用 Pro 模型与指定的 ThinkingBudget 进行对话
        const response = await chatWithGemini(textToSend || "请分析当前视觉上下文。", messages.map(m => ({ role: m.role, parts: [{ text: m.text }] })), mode === 'think', aiImages, toolType === 'research');
        resultMsg = { id: crypto.randomUUID(), role: 'model', text: response, context: contextForRedo };
      }
      updateSessionMessages([...newMessages, resultMsg]);
    } catch (error: any) { 
        updateSessionMessages([...newMessages, { id: crypto.randomUUID(), role: 'model', text: error.message || "请求失败，请检查 API 配置或网络状态", isError: true, context: contextForRedo }]); 
    } finally { setIsLoading(false); }
  };

