          const item = items.find(i => i.id === itemId);
          if (item?.content) setExternalRefImage(item.content);
      }
      setContextMenu(null);
  };

  const executeCaptureAction = async (action: 'chat' | 'canvas' | 'translate') => {
      if (!captureRect) return;
      let finalImg = capturedImage;
      if (!finalImg) {
          finalImg = await grabScreenPixels(captureRect, view.scale, view.x, view.y);
      }
      handleCaptureRegion(captureRect, action, finalImg);
      resetCapture();
  };

  return (
    <div 
      className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative"
      onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
      onDrop={(e) => { e.preventDefault(); e.stopPropagation(); const files = Array.from(e.dataTransfer.files); if (files.length > 0) files.forEach(f => handleFile(f)); else { const url = e.dataTransfer.getData('text/plain'); if (url) handleFile(url); } }}
    >
      <TopBar onExport={handleExportProject} onImport={handleImportProject} onCloudExport={handleCloudSave} onCloudImport={handleCloudLoad} onNewProject={() => { if (window.confirm("确定要新建画布吗？")) { resetHistory([]); setView({ x: 0, y: 0, scale: 1 }); setSelection([]); } }} />
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => { const spot = findPlacementSpot(800, 600, items); const f: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: spot.x, y: spot.y, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' }; const nextItems = [...items, f]; setItems(nextItems); commit(nextItems); setSelection([f.id]); }} recordingStatus={recordingStatus} onStartRecording={startRecording} onStopRecording={stopRecording} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={recordingTime} />

      <LayersPanel isOpen={showLayers} items={items} selection={selection.length > 0 ? selection[0] : null} onSelectItem={(id) => { setSelection([id]); const item = items.find(i => i.id === id); if (item) centerOnItem(item); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => { resetHistory(snap.items); setSelection([]); }} />

      <div className="w-full h-full">
        <Canvas 
          ref={canvasRef} 
          items={items} 
          selection={selection} 
          tool={tool} 
          view={view} 
          setView={setView} 
          setSelection={setSelection} 
          addItem={it => { const nextItems = [...items, it]; setItems(nextItems); commit(nextItems); }} 
          updateItem={handleUpdateItem} 
          updateItems={handleUpdateItems} 
          onContextMenu={(e, id) => { if (tool === 'point' || tool === 'capture') return; const sid = id || (selection.length === 1 ? selection[0] : undefined); setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId: sid }); }} 
          onDelete={id => handleDeleteItems([id])} 
          editMode={editMode} 
          editTool={editTool} 
          brushSize={brushSize} 
          brushColor={brushColor} 
          segments={segments} 
          onApplyEdit={handleApplyEdit} 
          onSelectItem={(id) => { const item = items.find(it => id === it.id); if (item && (item.type === ItemType.IMAGE || item.type === ItemType.VIDEO || item.type === ItemType.MODEL) && (item.content || item.modelUrl)) { if (isPickingPoint && pickingTargetId === item.id) return; if (tool === 'point' || tool === 'capture') return; setQuickLookItem(item); } }} 
          onPointPicked={handlePickPoint} 
          isPickingPoint={isPickingPoint && !!pickingTargetId} 
          onPointTagClick={(it, pt) => chatRef.current?.addPointReference(it.id, it.content || '', pt.label, [pt.y, pt.x])} 
          onPointRemoved={(it, pt) => chatRef.current?.requestObjectRemoval(it.id, it.content || '', pt.label, [pt.y, pt.x])} 
          showPointLabels={showPointLabels} 
          onDeletePointLocal={(iid, pid) => { const nextItems = items.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it); setItems(nextItems); commit(nextItems); }} 
          onMovePoint={(iid, pid, ny, nx) => setItems(prev => prev.map(item => item.id === iid ? { ...item, identifiedPoints: item.identifiedPoints?.map(p => p.id === pid ? { ...p, y: ny, x: nx } : p) } : item))} 
          onMovePointEnd={(iid, pid, from, to) => { const item = items.find(i => i.id === iid); if (item?.content) { const point = item.identifiedPoints?.find(p => p.id === pid); if (point) { chatRef.current?.appendMovementDescription(iid, item.content, point.label, from, to); } } }} 
          isTextMode={editSubMode === 'text'} 
          showGrid={showGrid} 
          onZoomToFit={zoomToFit} 
          onCaptureRegion={handleCaptureRegion} 
          onFloatingAction={handleFloatingAction} 
          expressionState={expressionState} 
          setExpressionState={setExpressionState} 
          inferenceState={inferenceState} 
          setInferenceState={setInferenceState} 
          currentEvolutionLevel={currentEvolutionLevel}
          captureState={captureState} 
          onExitToolMode={() => setTool('select')}
          activePartId={activePartId}
          onPartSelect={setActivePartId}
          onCameraChange={(id, s) => handleUpdateItem(id, { spatialConfig: s })}
          onLoadParts={(id, p) => handleUpdateItem(id, { partList: p })}
        />
      </div>

      {isCapturing && captureRect && (
        <div 
          className="fixed inset-0 z-[2000] pointer-events-none"
        >
           <div 
             className="absolute border-2 border-indigo-500 bg-indigo-500/5 shadow-[0_0_0_9999px_rgba(0,0,0,0.4)]"
             style={{ 
               left: captureRect.x * view.scale + view.x, 
               top: captureRect.y * view.scale + view.y, 
               width: captureRect.width * view.scale, 
               height: captureRect.height * view.scale 
             }} 
           />
        </div>
      )}

      {showCaptureMenu && captureRect && (
        <div 
          className="fixed z-[2010] p-1.5 bg-[#09090b]/95 backdrop-blur-xl border border-white/10 rounded-[20px] shadow-3xl pointer-events-auto flex flex-col gap-1.5"
          style={{ 
            left: (captureRect.x + captureRect.width) * view.scale + view.x + 10,
            top: (captureRect.y + captureRect.height) * view.scale + view.y,
            transform: 'translateY(-50%)'
          }}
        >
          {isGrabbingStream ? (
              <div className="w-10 h-32 flex flex-col items-center justify-center gap-4 bg-white/5 rounded-xl animate-pulse">
                  <RefreshIcon className="w-5 h-5 text-indigo-400 animate-spin" />
                  <span className="text-[8px] font-black text-indigo-400 uppercase vertical-text">Capture</span>
              </div>
          ) : (
              <>
              <div className="flex flex-col gap-1">
                <button onClick={() => executeCaptureAction('chat')} className="w-10 h-10 flex items-center justify-center bg-[#5546fe] text-white rounded-xl hover:bg-indigo-500 transition-all" title="发送到 Gemini"><MessageCircleIcon className="w-5 h-5" /></button>
                <button onClick={() => executeCaptureAction('translate')} className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white hover:bg-white/10 rounded-xl transition-all" title="智能翻译 (全屏捕获)"><LanguagesIcon className="w-5 h-5" /></button>
                <button onClick={() => executeCaptureAction('canvas')} className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white hover:bg-white/10 rounded-xl transition-all" title="生成局部变体"><SparklesIcon className="w-5 h-5" /></button>
              </div>
              <div className="h-px bg-white/10 mx-2" />
              <div className="flex flex-col gap-1">
                <button onClick={() => setActiveAnnoTool('number')} className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all ${activeAnnoTool === 'number' ? 'bg-red-500 text-white' : 'text-zinc-500 hover:bg-white/5'}`} title="序号标注"><span className="text-[11px] font-black">①</span></button>
                <button onClick={() => setActiveAnnoTool('arrow')} className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all ${activeAnnoTool === 'arrow' ? 'bg-indigo-500 text-white' : 'text-zinc-500 hover:bg-white/5'}`} title="箭头标注"><ArrowIcon className="w-5 h-5" /></button>
              </div>
              <div className="h-px bg-white/10 mx-2" />
              <button onClick={resetCapture} className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-red-500 hover:bg-red-500/10 rounded-xl transition-all" title="取消截图"><XIcon className="w-5 h-5" /></button>
              </>
          )}
        </div>
      )}

      <div className="fixed bottom-6 left-6 z-50 flex items-center gap-2 pointer-events-auto">
        <div className="bg-[#0c0c0e]/90 backdrop-blur-2xl border border-white/10 p-1 rounded-2xl flex items-center shadow-2xl">
          <button 
            onClick={() => setView(v => ({ ...v, scale: Math.max(0.01, v.scale / 1.2) }))}
            className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white transition-all hover:bg-white/5 rounded-xl"
          >
            <MinusIcon className="w-4 h-4" />
          </button>
          <div className="px-3 min-w-[60px] text-center">
            <span className="text-[10px] font-black font-mono text-white">{Math.round(view.scale * 100)}%</span>
          </div>
          <button 
            onClick={() => setView(v => ({ ...v, scale: Math.min(50, v.scale * 1.2) }))}
            className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white transition-all hover:bg-white/5 rounded-xl"
          >
            <PlusIcon className="w-4 h-4" />
          </button>
          <div className="w-px h-6 bg-white/5 mx-1" />
          <button 
            onClick={zoomToFit}
            className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white transition-all hover:bg-white/5 rounded-xl"
            title="适配屏幕"
          >
            <MaximizeIcon className="w-4 h-4" />
          </button>
          <button 
            onClick={() => setShowGrid(!showGrid)}
            className={`w-10 h-10 flex items-center justify-center transition-all rounded-xl ${showGrid ? 'text-indigo-400 bg-indigo-500/10' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`}
            title="网格开关 (G)"
          >
            <LayoutGridIcon className="w-4 h-4" />
          </button>
        </div>
      </div>

      <div className={`fixed bottom-10 left-1/2 -translate-x-1/2 z-[70] pointer-events-none flex flex-col items-center gap-4 transition-all duration-500 ease-in-out ${isChatExpanded ? 'translate-y-40 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <BottomBar 
             key={`${recipeRefreshTrigger}-${playstyleRefreshTrigger}`}
             lastGenerated={null} 
             externalRef={externalRefImage} 
             onExternalRefConsumed={() => setExternalRefImage(null)}
             onGenerate={(p, style, ratio, refs, count, level, res, recipeId, usePro) => handleGenerate('', p, { style, ratio, imageCount: count, artisticLevel: level, resolution: res, recipeId, usePro }, refs)}
             onExportRecipes={handleExportRecipes}
             onImportRecipes={handleImportRecipes}
          />
      </div>

      <div className={`fixed right-4 top-4 bottom-4 flex flex-col items-end transition-all duration-500 ease-in-out z-40 ${isPropertiesPanelOpen ? 'w-80' : 'w-16'}`}>
        {!isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(true)} className="w-14 h-14 rounded-full flex items-center justify-center transition-all shadow-2xl border bg-[#09090b] border-zinc-800 text-indigo-400 hover:scale-110"><SlidersIcon className="w-6 h-6" /></button>}
        <div className={`flex-1 w-full overflow-hidden transition-all duration-500 origin-right ${isPropertiesPanelOpen ? 'scale-100 opacity-100' : 'scale-90 opacity-0 pointer-events-none'}`}>
           <div className="relative h-full">
             {isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(false)} className="absolute top-4 right-4 z-[50] w-9 h-9 rounded-xl flex items-center justify-center bg-white/10 hover:bg-white/20 text-white transition-all border border-white/10 shadow-lg"><XIcon className="w-4 h-4" /></button>}
             <PropertiesPanel 
                selectedItem={selectedItem} 
                selectedItems={selectedItems} 
                onUpdateItem={handleUpdateItem} 
                onGenerate={handleGenerate} 
                onDelete={nid => handleDeleteItems([nid])} 
                onAutoPrompt={nid => analyzeImageForPrompt(items.find(it => it.id === nid)?.content || '').then(p => handleUpdateItem(nid, { prompt: p }))} 
                onSendToPrompt={nid => { const item = items.find(i => i.id === nid); if (item?.content) setExternalRefImage(item.content); }} 
                onSendToGemini={nid => { const item = items.find(i => i.id === nid); if (item?.content) chatRef.current?.addExternalAttachment(item.id, item.content); }} 
                onSyncPointsToGemini={(nid) => { const item = items.find(i => i.id === nid); if (item && item.content) chatRef.current?.addBulkPointReferences(item.id, item.content, item.identifiedPoints?.map(p => ({ label: p.label, point: [p.y, p.x] })) || []); }} 
                onEnterEditMode={() => setEditMode(true)} 
                onExitEditMode={() => { setEditMode(false); setSegments([]); }} 
                onFrameAction={handleFrameAction}
                editTool={editTool} setEditTool={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={handleApplyEdit} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleJSONAnalysis} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(nid, temp) => handleGenerate(nid, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} currentEvolutionLevel={currentEvolutionLevel} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onUpdatePoint={handleUpdatePoint} onClearAllPoints={handleClearAllPoints} onCommitPointChanges={handleCommitPointChanges} onAutoAlign={handleAutoAlignPoints} onClosePanel={() => setIsPropertiesPanelOpen(false)} 
                onFloatingAction={handleFloatingAction}
              />
           </div>
        </div>
      </div>

      {contextMenu && (
        <ContextMenu 
            x={contextMenu.x} y={contextMenu.y} 
            selectedItem={items.find(i => i.id === contextMenu.itemId) || null} 
            onSelect={action => handleContextMenuAction(action, contextMenu.itemId)} 
            onClose={() => setContextMenu(null)} 
            isMulti={selection.length > 1} 
        />
      )}
      <GeminiChatPanel ref={chatRef} onAddToCanvas={handleAddToCanvas} onReceiveSegments={(segs) => { setSegments(segs); setEditMode(true); }} onToggleExpand={setIsChatExpanded} />
      <input type="file" ref={fileInputRef} onChange={(e) => { const files = Array.from(e.target.files || []) as File[]; files.forEach(file => handleFile(file)); }} multiple className="hidden" accept="image/*,video/*,.webm,.obj" />

      {quickLookItem && (
        <div className="fixed inset-0 z-[1000] bg-black/95 backdrop-blur-2xl flex flex-col animate-in fade-in duration-300 pointer-events-auto">
          <div className="absolute inset-0 z-0" onClick={() => setQuickLookItem(null)} />
          <div className="h-16 flex items-center justify-between px-8 border-b border-white/5 relative z-10" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <EyeIcon className="w-5 h-5 text-indigo-400" />
               <span className="text-[12px] font-black text-white uppercase tracking-[0.3em]">沉浸式预览模式</span>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={() => handleSpatialNavigate('ArrowLeft')} className="p-3 text-zinc-400 hover:text-white rounded-xl hover:bg-white/5 transition-all"><ChevronLeftIcon className="w-5 h-5" /></button>
                <button onClick={() => handleSpatialNavigate('ArrowRight')} className="p-3 text-zinc-400 hover:text-white rounded-xl hover:bg-white/5 transition-all"><ChevronRightIcon className="w-5 h-5" /></button>
                <div className="w-px h-6 bg-white/10 mx-2" />
                <button onClick={() => setQuickLookItem(null)} className="p-3 text-zinc-400 hover:text-white rounded-xl hover:bg-white/5 transition-all"><XIcon className="w-6 h-6" /></button>
            </div>
          </div>
          <div className="flex-1 flex items-center justify-center p-12 overflow-hidden relative z-10" onClick={e => e.stopPropagation()}>
             {quickLookItem.type === ItemType.IMAGE ? (
                <img src={quickLookItem.content} className="max-w-full max-h-full object-contain shadow-[0_40px_100px_rgba(0,0,0,0.8)] rounded-2xl" />
             ) : quickLookItem.type === ItemType.MODEL && quickLookItem.modelUrl ? (
                <div className="w-full h-full max-w-4xl aspect-square rounded-3xl overflow-hidden shadow-3xl bg-[#111113]">
                  <ModelViewport 
                    url={quickLookItem.modelUrl} 
                    viewAngle={quickLookItem.viewAngle} 
                    cameraMode={quickLookItem.cameraMode}
                    explodeFactor={quickLookItem.explodeFactor} 
                    activePartId={activePartId}
                    highlightedPartIds={quickLookItem.highlightedPartIds}
                    onPartSelect={setActivePartId}
                    onCameraChange={(s) => handleUpdateItem(quickLookItem.id, { spatialConfig: s })}
                    width={1000}
                    height={1000}
                    spatialConfig={quickLookItem.spatialConfig}
                    partCMFMap={quickLookItem.partCMFMap}
                  />
                </div>
             ) : (
                <video src={quickLookItem.content} controls autoPlay className="max-w-full max-h-full rounded-2xl shadow-2xl" />
             )}
          </div>
          <div className="p-10 text-center bg-gradient-to-t from-black to-transparent relative z-10" onClick={e => e.stopPropagation()}>
               <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.4em]">ESC TO CLOSE • ARROWS TO NAVIGATE</p>
          </div>
        </div>
      )}

      {recipePanelData && (
          <DesignRecipePanel 
            initialInstruction={recipePanelData.instruction}
            exampleImages={recipePanelData.images}
            onSave={handleSaveRecipe}
            onClose={() => setRecipePanelData(null)}
          />
      )}

      {isExtractingRecipe && (
          <div className="fixed inset-0 z-[1000] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center gap-6 animate-in fade-in duration-500">
              <div className="relative">
                  <div className="w-24 h-24 rounded-full border-2 border-indigo-500/20 border-t-indigo-500 animate-spin" />
                  <div className="absolute inset-0 flex items-center justify-center">
                      <FlaskIcon className="w-8 h-8 text-indigo-400 animate-pulse" />
                  </div>
              </div>
              <div className="space-y-2 text-center">
                  <h2 className="text-white font-black text-lg uppercase tracking-[0.4em]">基因解构中</h2>
                  <p className="text-zinc-400 text-sm font-bold uppercase tracking-widest">AI 正在深度解析选定样本的审美配方...</p>
              </div>
          </div>
      )}
    </div>
  );
};
export default App;

export type ToolType = 'select' | 'hand' | 'image' | 'text' | 'rectangle' | 'circle' | 'line' | 'arrow' | 'pen' | 'point' | 'capture' | 'frame';
export type EditToolType = 'lasso' | 'brush' | 'rect' | 'wand' | 'eraser';
export type ResolutionType = '1K' | '2K' | '4K';
export type EditSubMode = 'paint' | 'text';

export enum ItemType {
  IMAGE = 'IMAGE',
  VIDEO = 'VIDEO',
  TEXT = 'TEXT',
  SHAPE = 'SHAPE',
  PEN = 'PEN',
  FRAME = 'FRAME',
  MODEL = 'MODEL'
}

export interface ImageFilters {
  hue: number;
  saturation: number;
  brightness: number;
  contrast: number;
  opacity: number;
}

export interface SpatialConfig {
  azimuth: number;   // 0-360
  elevation: number; // -90 to 90
  distance: number;  // zoom level
  fov: number;       // perspective
}

export interface PartCMF {
  color?: string;
  metalness?: number;
  roughness?: number;
  emissiveIntensity?: number;
  opacity?: number;
}

export interface InferenceSettings {
    prompt: string;
    influence: number; // 0-1
    style: string;
    recipeId?: string;
    subjectType?: 'industrial' | 'organic' | 'character';
}

export interface GenerationSettings {
    style: string;
    ratio: string;
    imageCount: number;
    artisticLevel: number;
    resolution: ResolutionType;
    spatialConfig?: SpatialConfig;
    recipeId?: string;
    inferenceConfig?: InferenceSettings;
    batchActions?: any[]; // 用于特征点批量重构
    usePro?: boolean; // 是否使用 Pro 模型以获得更高质量
}

export interface Segment {
  label: string;
  box_2d: [number, number, number, number]; // [ymin, xmin, ymax, xmax] in 0-1000 scale
  description: string;
}

export interface SemanticGroup {
  id: string;
  name: string;
  color: string;
  isActive: boolean;
}

export interface IdentifiedPoint {
  id: string;
  y: number; // 0-1000 归一化坐标
  x: number; // 0-1000 归一化坐标
  label: string; // 用于 UI 显示的唯一序号（如 1, 2, 3）
  description?: string; // AI 识别出的该位置特征描述
  isMoving?: boolean;
  modifiedDescription?: string; // 用户修改后的描述
  isRemoving?: boolean; // 标记为待移除
  pairingId?: string; // 关联的配对点 ID (跨图移植)
  pairingSourceItemId?: string; // 来源图片 ID
  originalPos?: [number, number]; // 拖动前的坐标
  groupId?: string; // 所属语义组 ID
}

export interface CanvasItem {
  id: string;
  type: ItemType;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  content: string;
  prompt?: string;
  style?: string;
  status: 'empty' | 'loading' | 'generated' | 'error';
  aspectRatio?: string;
  filters?: ImageFilters;
  locked?: boolean;
  links?: string[]; 
  isChild?: boolean;
  maskData?: string; 
  identifiedPoints?: IdentifiedPoint[]; 
  semanticGroups?: SemanticGroup[]; // 语义组配置
  spatialConfig?: SpatialConfig;
  inferenceInfluence?: number; 
  essence?: string; 
  // 文本排版属性
  fontSize?: number;
  fontWeight?: string | number;
  textColor?: string;
  // 3D 模型属性
  modelUrl?: string; // 模型 Blob URL 或静态地址
  viewAngle?: 'front' | 'top' | 'side' | 'perspective'; // 固定视口角度
  cameraMode?: 'perspective' | 'orthographic'; // 显式投影模式
  explodeFactor?: number; // 爆炸强度 (0-1)
  activePartId?: string; // 当前联动选中的零件 UUID
  highlightedPartIds?: string[]; // 语义指令高亮的部件列表
  colorSeed?: number; // 随机着色种子
  partColorMap?: Record<string, string>; // 已弃用，建议使用 partCMFMap
  partCMFMap?: Record<string, PartCMF>; // 精细材质映射 {partId: PartCMF}
  savedViews?: SpatialConfig[]; // 持久化视角
  partList?: string[]; // 零件名称列表
}

export interface ViewState {
  x: number;
  y: number;
  scale: number;
}

export interface Point {
  x: number;
  y: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ExpressionState {
  itemId: string;
  isOpen: boolean;
}

export interface DesignRecipe {
  id: string;
  name: string;
  instruction: string;
  exampleImages: string[]; 
  createdAt: number;
}

export interface Playstyle {
  id: string;
  name: string;
  description: string;
  template: string; // "A futuristic {{subject}}, translucent shell..."
  category: string; // "industrial", "art", "material"
  previewImage?: string;
  createdAt: number;
}

export interface ProjectPackage {
  version: string;
  timestamp: number;
  items: CanvasItem[];
  view: ViewState;
  recipes?: DesignRecipe[]; 
  playstyles?: Playstyle[];
}

export interface ChatFolder {
  id: string;
  name: string;
  createdAt: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  images?: string[]; 
  originalImages?: string[]; 
  videoUrl?: string;
  isJson?: boolean;
  isCollapsed?: boolean;
  context?: {
      prompt: string;
      attachments: Attachment[];
      toolType: string | null;
  };
  isError?: boolean;
}

