    const playstyles = await getAllPlaystyles();
    const pkg: ProjectPackage = { version: "1.1", timestamp: Date.now(), items, view, recipes, playstyles };
    const blob = new Blob([JSON.stringify(pkg)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `Infinite_Imagination_Full_${Date.now()}.json`; a.click(); URL.revokeObjectURL(url);
  }, [items, view]);

  const handleImportProject = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const pkg = JSON.parse(e.target?.result as string) as ProjectPackage;
        if (pkg.items && Array.isArray(pkg.items)) { 
            resetHistory(pkg.items); 
            if (pkg.view) setView(pkg.view); 
            if (pkg.recipes) {
                for (const r of pkg.recipes) { await saveRecipe(r); }
                setRecipeRefreshTrigger(prev => prev + 1);
            }
            if (pkg.playstyles) {
                for (const ps of pkg.playstyles) { await savePlaystyle(ps); }
                setPlaystyleRefreshTrigger(prev => prev + 1);
            }
            setSelection([]); setEditMode(false); 
        } else { alert("无效的存档文件格式。"); }
      } catch (err) { alert("导入失败，请检查 JSON 格式。"); }
    };
    reader.readAsText(file);
  }, [resetHistory, setView]);

  const handleExportRecipes = async () => {
    const recipes = await getAllRecipes();
    const blob = new Blob([JSON.stringify(recipes)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `Design_Recipes_${Date.now()}.json`; a.click(); URL.revokeObjectURL(url);
  };

  const handleImportRecipes = async (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            const data = Array.isArray(parsed) ? parsed : [parsed];
            for (const r of data) { 
                if (r.name && r.instruction) {
                    await saveRecipe({ ...r, id: r.id || crypto.randomUUID(), createdAt: r.createdAt || Date.now() }); 
                }
            }
            setRecipeRefreshTrigger(prev => prev + 1);
            alert(`✅ 成功导入 ${data.length} 个设计食谱！`);
        } catch (err) { alert("食谱导入失败，请检查 file 格式。"); }
    };
    reader.readAsText(file);
  };

  const handleSpatialNavigate = useCallback((direction: string) => {
    const activeId = quickLookItem?.id || (selection.length === 1 ? selection[0] : null);
    if (!activeId) return;
    const current = items.find(i => i.id === activeId); if (!current) return;
    const candidates = items.filter(i => { if (i.id === activeId || i.type === ItemType.FRAME || !i.content) return false; const cx = i.x + i.width/2, cy = i.y + i.height/2; const curX = current.x + current.width/2, curY = current.y + current.height/2; if (direction === 'ArrowRight') return cx > curX + 10; if (direction === 'ArrowLeft') return cx < curX - 10; if (direction === 'ArrowUp') return cy < curY - 10; if (direction === 'ArrowDown') return cy > curY + 10; return false; });
    const next = candidates.sort((a, b) => { const curX = current.x + current.width/2, curY = current.y + current.height/2; const da = Math.hypot((a.x + a.width/2) - curX, (a.y + a.height/2) - curY); const db = Math.hypot((b.x + b.width/2) - curX, (b.y + b.height/2) - curY); return da - db; })[0];
    if (next) { 
        if (quickLookItem) setQuickLookItem(next); 
        else { 
            setSelection([next.id]); 
            centerOnItem(next); 
        } 
    }
  }, [items, quickLookItem, selection, centerOnItem]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement; if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') { e.preventDefault(); if (e.shiftKey) redo(); else undo(); return; }
      if (e.key === 'Delete' || e.key === 'Backspace') { if (selection.length > 0) handleDeleteItems(selection); }
      if (e.key === ' ') { e.preventDefault(); if (quickLookItem) setQuickLookItem(null); else if (selectedItem) setQuickLookItem(selectedItem); }
      if (e.key === 'Escape') { if (quickLookItem) setQuickLookItem(null); else if (editMode) setEditMode(false); else if (isPickingPoint) setIsPickingPoint(false); setExpressionState({ itemId: '', isOpen: false }); setInferenceState({ itemId: '', isOpen: false }); setTool('select'); }
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) { e.preventDefault(); if (quickLookItem || selection.length === 1) { handleSpatialNavigate(e.key); } else if (selection.length > 0) { const step = e.shiftKey ? 10 : 1; const updates = selection.map(id => { const item = items.find(i => i.id === id); if (!item) return null; let nx = item.x, ny = item.y; if (e.key === 'ArrowUp') ny -= step; if (e.key === 'ArrowDown') ny += step; if (e.key === 'ArrowLeft') nx -= step; if (e.key === 'ArrowRight') nx += step; return { id, updates: { x: nx, y: ny } }; }).filter(Boolean) as { id: string, updates: Partial<CanvasItem> }[]; if (updates.length > 0) { handleUpdateItems(updates); commit(items.map(it => { const upd = updates.find(u => u.id === it.id); return upd ? { ...it, ...upd.updates } : it; })); } } }
      if (e.key.toLowerCase() === 'v') setTool('select');
      if (e.key.toLowerCase() === 'h') setTool('hand');
      if (e.key.toLowerCase() === 'r') setTool('point');
      if (e.key.toLowerCase() === 'c') setTool('capture');
      if (e.key.toLowerCase() === 'g') setShowGrid(prev => !prev);
      if (e.key.toLowerCase() === 't') setTool('text');
    };
    window.addEventListener('paste', handlePaste); window.addEventListener('keydown', handleKeyDown); 
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('paste', handlePaste); };
  }, [selection, items, redo, undo, commit, editMode, quickLookItem, selectedItem, handleSpatialNavigate, isPickingPoint, handlePaste]);

  const startRecording = async (resolution: string) => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: { cursor: "always" } as any, audio: false }); streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream); mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.ondataavailable = (event) => { if (event.data.size > 0) recordedChunksRef.current.push(event.data); };
      mediaRecorder.onstop = () => { const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `无限想象-${Date.now()}.webm`; a.click(); setRecordingStatus('idle'); setRecordingTime(0); if (timerRef.current) window.clearInterval(timerRef.current); };
      mediaRecorder.start(); setRecordingStatus('recording'); timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch (err) {}
  };
  const stopRecording = () => { mediaRecorderRef.current?.stop(); streamRef.current?.getTracks().forEach(track => track.stop()); };

  const handleSaveRecipe = async (name: string, instruction: string) => {
    if (!recipePanelData) return;
    const newRecipe: DesignRecipe = { id: crypto.randomUUID(), name, instruction, exampleImages: recipePanelData.images, createdAt: Date.now() };
    await saveRecipe(newRecipe); setRecipePanelData(null); setRecipeRefreshTrigger(prev => prev + 1);
    alert(`✅ 食谱 "${name}" 已保存！`);
  };

  const handleContextMenuAction = (action: string, itemId?: string) => {
      const selected = items.filter(i => selection.includes(i.id));

      if (action === 'frame_selection' && selected.length > 0) {
          const minX = Math.min(...selected.map(i => i.x)), minY = Math.min(...selected.map(i => i.y));
          const maxX = Math.max(...selected.map(i => i.x + i.width)), maxY = Math.max(...selected.map(i => i.y + i.height));
          const padding = 40;
          const newFrame: CanvasItem = {
              id: crypto.randomUUID(),
              type: ItemType.FRAME,
              x: minX - padding,
              y: minY - padding,
              width: (maxX - minX) + padding * 2,
              height: (maxY - minY) + padding * 2,
              rotation: 0,
              content: '新组合画框',
              status: 'empty'
          };
          const nextItems = [...items, newFrame];
          setItems(nextItems); commit(nextItems); setSelection([newFrame.id]);
      } else if (action === 'gridify' && selected.length > 0) {
          const sorted = [...selected].sort((a, b) => a.y - b.y || a.x - b.x);
          const cols = Math.ceil(Math.sqrt(sorted.length));
          const gap = 40;
          const startX = Math.min(...selected.map(i => i.x));
          const startY = Math.min(...selected.map(i => i.y));
          const itemW = 512, itemH = 512;

          const updates = sorted.map((it, nid) => {
              const r = Math.floor(nid / cols), c = nid % cols;
              return { id: it.id, updates: { x: startX + c * (itemW + gap), y: startY + r * (itemH + gap), width: itemW, height: itemH } };
          });
          handleUpdateItems(updates);
          commit(items.map(it => {
              const u = updates.find(up => u.id === it.id);
              return u ? { ...it, ...u.updates } : it;
          }));
      } else if (action === 'delete') {
          handleDeleteItems(selection);
      } else if (action === 'copy') {
          handleCopy(null);
      } else if (action === 'send_to_gemini') {
          const item = items.find(i => i.id === itemId);
          if (item?.content) chatRef.current?.addExternalAttachment(item.id, item.content);
      } else if (action === 'send_to_prompt') {
          const item = items.find(i => i.id === itemId);
          if (item?.content) setExternalRefImage(item.content);
      }
      setContextMenu(null);
  };

