                onSyncPointsToGemini={(nid) => { const item = items.find(i => i.id === nid); if (item && item.content) chatRef.current?.addBulkPointReferences(item.id, item.content, item.identifiedPoints?.map(p => ({ label: p.label, point: [p.y, p.x] })) || []); }} 
                onEnterEditMode={() => setEditMode(true)} 
                onExitEditMode={() => { setEditMode(false); setSegments([]); }} 
                onFrameAction={handleFrameAction}
                editTool={editTool} setEditTool={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={handleApplyEdit} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleJSONAnalysis} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(nid, temp) => handleGenerate(nid, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} currentEvolutionLevel={currentEvolutionLevel} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onUpdatePoint={handleUpdatePoint} onClearAllPoints={handleClearAllPoints} onCommitPointChanges={handleCommitPointChanges} onAutoAlign={handleAutoAlignPoints} onClosePanel={() => setIsPropertiesPanelOpen(false)} 
                onFloatingAction={handleFloatingAction}
              />
           </div>
        </div>
      </div>

      {contextMenu && (
        <ContextMenu 
            x={contextMenu.x} y={contextMenu.y} 
            selectedItem={items.find(i => i.id === contextMenu.itemId) || null} 
            onSelect={action => handleContextMenuAction(action, contextMenu.itemId)} 
            onClose={() => setContextMenu(null)} 
            isMulti={selection.length > 1} 
        />
      )}
      <GeminiChatPanel ref={chatRef} onAddToCanvas={handleAddToCanvas} onReceiveSegments={(segs) => { setSegments(segs); setEditMode(true); }} onToggleExpand={setIsChatExpanded} />
      <input type="file" ref={fileInputRef} onChange={(e) => { const files = Array.from(e.target.files || []) as File[]; files.forEach(file => handleFile(file)); }} multiple className="hidden" accept="image/*,video/*,.webm,.obj" />

      {quickLookItem && (
        <div className="fixed inset-0 z-[1000] bg-black/95 backdrop-blur-2xl flex flex-col animate-in fade-in duration-300 pointer-events-auto">
          <div className="absolute inset-0 z-0" onClick={() => setQuickLookItem(null)} />
          <div className="h-16 flex items-center justify-between px-8 border-b border-white/5 relative z-10" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <EyeIcon className="w-5 h-5 text-indigo-400" />
               <span className="text-[12px] font-black text-white uppercase tracking-[0.3em]">沉浸式预览模式</span>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={() => handleSpatialNavigate('ArrowLeft')} className="p-3 text-zinc-400 hover:text-white rounded-xl hover:bg-white/5 transition-all"><ChevronLeftIcon className="w-5 h-5" /></button>
                <button onClick={() => handleSpatialNavigate('ArrowRight')} className="p-3 text-zinc-400 hover:text-white rounded-xl hover:bg-white/5 transition-all"><ChevronRightIcon className="w-5 h-5" /></button>
                <div className="w-px h-6 bg-white/10 mx-2" />
                <button onClick={() => setQuickLookItem(null)} className="p-3 text-zinc-400 hover:text-white rounded-xl hover:bg-white/5 transition-all"><XIcon className="w-6 h-6" /></button>
            </div>
          </div>
          <div className="flex-1 flex items-center justify-center p-12 overflow-hidden relative z-10" onClick={e => e.stopPropagation()}>
             {quickLookItem.type === ItemType.IMAGE ? (
                <img src={quickLookItem.content} className="max-w-full max-h-full object-contain shadow-[0_40px_100px_rgba(0,0,0,0.8)] rounded-2xl" />
             ) : quickLookItem.type === ItemType.MODEL && quickLookItem.modelUrl ? (
                <div className="w-full h-full max-w-4xl aspect-square rounded-3xl overflow-hidden shadow-3xl bg-[#111113]">
                  <ModelViewport 
                    url={quickLookItem.modelUrl} 
                    viewAngle={quickLookItem.viewAngle} 
                    cameraMode={quickLookItem.cameraMode}
                    explodeFactor={quickLookItem.explodeFactor} 
                    activePartId={activePartId}
                    highlightedPartIds={quickLookItem.highlightedPartIds}
                    onPartSelect={setActivePartId}
                    onCameraChange={(s) => handleUpdateItem(quickLookItem.id, { spatialConfig: s })}
                    width={1000}
                    height={1000}
                    spatialConfig={quickLookItem.spatialConfig}
                    partCMFMap={quickLookItem.partCMFMap}
                  />
                </div>
             ) : (
                <video src={quickLookItem.content} controls autoPlay className="max-w-full max-h-full rounded-2xl shadow-2xl" />
             )}
          </div>
          <div className="p-10 text-center bg-gradient-to-t from-black to-transparent relative z-10" onClick={e => e.stopPropagation()}>
               <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.4em]">ESC TO CLOSE • ARROWS TO NAVIGATE</p>
          </div>
        </div>
      )}

      {recipePanelData && (
          <DesignRecipePanel 
            initialInstruction={recipePanelData.instruction}
            exampleImages={recipePanelData.images}
            onSave={handleSaveRecipe}
            onClose={() => setRecipePanelData(null)}
          />
      )}

      {isExtractingRecipe && (
          <div className="fixed inset-0 z-[1000] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center gap-6 animate-in fade-in duration-500">
              <div className="relative">
                  <div className="w-24 h-24 rounded-full border-2 border-indigo-500/20 border-t-indigo-500 animate-spin" />
                  <div className="absolute inset-0 flex items-center justify-center">
                      <FlaskIcon className="w-8 h-8 text-indigo-400 animate-pulse" />
                  </div>
              </div>
              <div className="space-y-2 text-center">
                  <h2 className="text-white font-black text-lg uppercase tracking-[0.4em]">基因解构中</h2>
                  <p className="text-zinc-400 text-sm font-bold uppercase tracking-widest">AI 正在深度解析选定样本的审美配方...</p>
              </div>
          </div>
      )}
    </div>
  );
};
export default App;

export type ToolType = 'select' | 'hand' | 'image' | 'text' | 'rectangle' | 'circle' | 'line' | 'arrow' | 'pen' | 'point' | 'capture' | 'frame';
export type EditToolType = 'lasso' | 'brush' | 'rect' | 'wand' | 'eraser';
export type ResolutionType = '1K' | '2K' | '4K';
export type EditSubMode = 'paint' | 'text';

export enum ItemType {
  IMAGE = 'IMAGE',
  VIDEO = 'VIDEO',
  TEXT = 'TEXT',
  SHAPE = 'SHAPE',
  PEN = 'PEN',
  FRAME = 'FRAME',
  MODEL = 'MODEL'
}

export interface ImageFilters {
  hue: number;
  saturation: number;
  brightness: number;
  contrast: number;
  opacity: number;
}

export interface SpatialConfig {
  azimuth: number;   // 0-360
  elevation: number; // -90 to 90
  distance: number;  // zoom level
  fov: number;       // perspective
  explodeFactor?: number; // 记录保存视角时的爆炸状态
}

export interface PartCMF {
  color?: string;
  metalness?: number;
  roughness?: number;
  emissiveIntensity?: number;
  opacity?: number;
}

export interface InferenceSettings {
    prompt: string;
    influence: number; // 0-1
    style: string;
    recipeId?: string;
    subjectType?: 'industrial' | 'organic' | 'character';
}

export interface GenerationSettings {
    style: string;
    ratio: string;
    imageCount: number;
    artisticLevel: number;
    resolution: ResolutionType;
    spatialConfig?: SpatialConfig;
    recipeId?: string;
    inferenceConfig?: InferenceSettings;
    batchActions?: any[]; // 用于特征点批量重构
    usePro?: boolean; // 是否使用 Pro 模型以获得更高质量
}

export interface Segment {
  label: string;
  box_2d: [number, number, number, number]; // [ymin, xmin, ymax, xmax] in 0-1000 scale
  description: string;
}

export interface IdentifiedPoint {
  id: string;
  y: number; // 0-1000 归一化坐标
  x: number; // 0-1000 归一化坐标
  label: string; // 用于 UI 显示的唯一序号（如 1, 2, 3）
  description?: string; // AI 识别出的该位置特征描述
  isMoving?: boolean;
  modifiedDescription?: string; // 用户修改后的描述
  isRemoving?: boolean; // 标记为待移除
  pairingId?: string; // 关联的配对点 ID (跨图移植)
  pairingSourceItemId?: string; // 来源图片 ID
  originalPos?: [number, number]; // 拖动前的坐标
}

export interface CanvasItem {
  id: string;
  type: ItemType;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  content: string;
  prompt?: string;
  style?: string;
  status: 'empty' | 'loading' | 'generated' | 'error';
  aspectRatio?: string;
  filters?: ImageFilters;
  locked?: boolean;
  links?: string[]; 
  isChild?: boolean;
  maskData?: string; 
  identifiedPoints?: IdentifiedPoint[]; 
  spatialConfig?: SpatialConfig;
  inferenceInfluence?: number; 
  base_prompt?: string;
  essence?: string; 
  // 文本排版属性
  fontSize?: number;
  fontWeight?: string | number;
  textColor?: string;
  // 3D 模型属性
  modelUrl?: string; // 模型 Blob URL 或静态地址
  viewAngle?: 'front' | 'top' | 'side' | 'perspective'; // 固定视口角度
  cameraMode?: 'perspective' | 'orthographic'; // 显式投影模式
  explodeFactor?: number; // 爆炸强度 (0-1)
  activePartId?: string; // 当前联动选中的零件 UUID
  highlightedPartIds?: string[]; // 语义指令高亮的部件列表
  colorSeed?: number; // 随机着色种子
  partColorMap?: Record<string, string>; // 已弃用，建议使用 partCMFMap
  partCMFMap?: Record<string, PartCMF>; // 精细材质映射 {partId: PartCMF}
  savedViews?: SpatialConfig[]; // 持久化视角
  partList?: string[]; // 零件名称列表
}

export interface ViewState {
  x: number;
  y: number;
  scale: number;
}

export interface Point {
  x: number;
  y: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ExpressionState {
  itemId: string;
  isOpen: boolean;
}

export interface DesignRecipe {
  id: string;
  name: string;
  instruction: string;
  exampleImages: string[]; 
  createdAt: number;
}

export interface Playstyle {
  id: string;
  name: string;
  description: string;
  template: string; // "A futuristic {{subject}}, translucent shell..."
  category: string; // "industrial", "art", "material"
  previewImage?: string;
  createdAt: number;
}

export interface ProjectPackage {
  version: string;
  timestamp: number;
  items: CanvasItem[];
  view: ViewState;
  recipes?: DesignRecipe[]; 
  playstyles?: Playstyle[];
}

export interface ChatFolder {
  id: string;
  name: string;
  createdAt: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  images?: string[]; 
  originalImages?: string[]; 
  videoUrl?: string;
  isJson?: boolean;
  isCollapsed?: boolean;
  context?: {
      prompt: string;
      attachments: Attachment[];
      toolType: string | null;
  };
  isError?: boolean;
}

export interface Attachment {
  id: string;
  original: string;
  marked: string; 
  maskData?: string; 
  points: Record<string, [number, number]>;
  sourceId?: string; 
}

export interface ChatSession {
  id: string;
  title: string;
  messages: ChatMessage[];
  createdAt: number;
  folderId?: string;
}

import { useState, useEffect, useMemo, useRef } from 'react';
import React from 'react';
import { CanvasItem, ItemType, EditToolType, GenerationSettings, SpatialConfig, IdentifiedPoint } from '../types';
import { 
  SparklesIcon, RefreshIcon, EraserIcon, 
  ScissorsIcon, VectorIcon, 
  UpscaleIcon, SlidersIcon, ChevronRightIcon,
  ChevronLeftIcon, SquareIcon, TrashIcon,
  FileIcon, CopyIcon, EvolutionIcon,
  LassoIcon, BrushIcon, TypeIcon, CreativeScaleIcon, ZapIcon,
  PaletteIcon, XIcon, FocusIcon,
  MessageCircleIcon, TargetIcon, WandIcon, LinkIcon, CameraIcon,
  MaximizeIcon, BoxIcon, CheckIcon, RotateCcwIcon, MagicCurveIcon,
  MergeIcon, FrameIcon, ExpandIcon, LayoutGridIcon, GripIcon, ShuffleIcon,
  GalleryIcon, TerminalIcon, PlusIcon,
  ArrowIcon, FlaskIcon, EyeIcon, ShuffleIcon as ShuffleIconLucide
} from './Icons';
import SpatialController from './SpatialController';
import { getEvolutionStage } from '../services/evolutionService';

type PanelView = 'main' | 'variations' | 'edit_area' | 'adjust_colors' | 'change_bg' | 'evolution' | 'spatial' | 'transplant' | 'model_3d';

interface PropertiesPanelProps {
  selectedItem: CanvasItem | null;
  selectedItems?: CanvasItem[];
  onUpdateItem: (id: string, updates: Partial<CanvasItem>) => void;
  onGenerate: (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>) => void;
  onDelete: (id: string) => void;
  onAutoPrompt?: (id: string) => Promise<void>;
  onEnterEditMode?: (tool: EditToolType) => void;
  onExitEditMode?: () => void;
  initialView?: {view: string, ts: number} | null;
  onSendToPrompt?: (id: string) => void;
  onSendToGemini?: (id: string) => void;
  onSyncPointsToGemini?: (id: string) => void;
  onFrameAction?: (id: string, action: 'merge' | 'expand' | 'crop') => void;
  editTool?: EditToolType;
  setEditTool?: (tool: EditToolType) => void;
  brushSize?: number;
  setBrushSize?: (size: number) => void;
  onApplyEdit?: (prompt: string) => void;
  onClearMask?: () => void;
  onJSONAnalysis?: (id: string) => void;
  isAnalyzingJSON?: boolean;
  onStartPickPoint?: (id: string, temperature: number) => void;
  isPickingPoint?: boolean;
  currentEvolutionLevel?: number;
  isCncMode: boolean;
  setIsCncMode: (val: boolean) => void;
  onUpdatePoint?: (itemId: string, pointId: string, updates: Partial<IdentifiedPoint>) => void;
  onClearAllPoints?: (itemId: string) => void;
  onCommitPointChanges?: (itemId: string) => void;
  onAutoAlign?: (sourceId: string, targetId: string) => Promise<void>;
  onClosePanel?: () => void;
  onFloatingAction?: (id: string, action: string) => void;
}

const DEFAULT_SPATIAL: SpatialConfig = {
    azimuth: 45,
    elevation: 30,
    distance: 12,
    fov: 45
};

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ 
  selectedItem, selectedItems = [], onUpdateItem, onGenerate, onDelete, onAutoPrompt, 
  onEnterEditMode, onExitEditMode, initialView, onSendToPrompt, onSendToGemini, onSyncPointsToGemini,
  onFrameAction, editTool, setEditTool, brushSize = 30, setBrushSize, onApplyEdit, onClearMask,
  onJSONAnalysis, isAnalyzingJSON, onStartPickPoint, isPickingPoint, currentEvolutionLevel = 60,
  isCncMode, setIsCncMode, onUpdatePoint, onClearAllPoints, onCommitPointChanges, onAutoAlign, onClosePanel,
  onFloatingAction
}) => {
  const [currentView, setCurrentView] = useState<PanelView>('main');
  const [localPrompt, setLocalPrompt] = useState('');
  const [modelCommand, setModelCommand] = useState('');
  const [activeTab, setActiveTab] = useState<'actions' | 'details' | 'nodes'>('actions');
  const [artisticLevel, setArtisticLevel] = useState(currentEvolutionLevel);
  const [pickTemperature, setPickTemperature] = useState(0.8);
  const [isAligning, setIsAligning] = useState(false);
  const [isSwapped, setIsSwapped] = useState(false); 
  const [usePro, setUsePro] = useState(false);

  const textInputRef = useRef<HTMLTextAreaElement>(null);

  const currentStage = useMemo(() => getEvolutionStage(artisticLevel), [artisticLevel]);

  const isTransplantMode = useMemo(() => {
    return selectedItems.length === 2 && selectedItems.every(i => i.type === ItemType.IMAGE);
  }, [selectedItems]);

  useEffect(() => {
    if (initialView) {
        setCurrentView(initialView.view as PanelView);
        if (initialView.view === 'edit_area') onEnterEditMode?.('brush');
    } else {
        setCurrentView('main');
    }
  }, [initialView?.ts, selectedItem?.id]);

  useEffect(() => {
    if (selectedItem) setLocalPrompt(selectedItem.prompt || '');
    if (selectedItem?.type === ItemType.TEXT) {
        setTimeout(() => {
            textInputRef.current?.focus();
            if (selectedItem.content === '在此输入内容') {
                textInputRef.current?.select();
            }
        }, 100);
    }
  }, [selectedItem?.id, selectedItem?.prompt, selectedItem?.type]);

  useEffect(() => {
    setArtisticLevel(currentEvolutionLevel);
  }, [currentEvolutionLevel]);

  const handleAutoAlignInternal = async (targetId: string, sourceId: string) => {
    if (!onAutoAlign) return;
    setIsAligning(true);
    try {
      await onAutoAlign(sourceId, targetId);
    } finally {
      setIsAligning(false);
    }
  };

  const handleFontSizeChange = (size: number) => {
    if (selectedItem) {
      onUpdateItem(selectedItem.id, { fontSize: size });
    }
  };

  if (!selectedItem && !isTransplantMode) {
    return (
      <div className="w-full h-full bg-[#09090b] border border-zinc-800 rounded-[24px] p-8 flex flex-col items-center justify-center text-zinc-500 shadow-2xl">
         <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-zinc-800/50 rounded-[20px] flex items-center justify-center mx-auto border border-zinc-700/50">
                <SparklesIcon className="w-8 h-8 text-indigo-400 opacity-50" />
            </div>
            <div className="space-y-2">
                <h3 className="font-black text-white text-[12px] uppercase tracking-[0.2em]">工作台</h3>
                <p className="text-[11px] text-zinc-500 leading-relaxed max-w-[180px] mx-auto">选择一个画框、图像或 3D 模型来编辑其属性、生成变体或应用空间控制。</p>
            </div>
         </div>
      </div>
    );
  }

  const handleBack = () => {
    setCurrentView('main');
    onExitEditMode?.();
  };

  const renderModelPanel = () => {
    if (!selectedItem || selectedItem.type !== ItemType.MODEL) return null;

    const handleCaptureView = () => {
        if (!selectedItem.spatialConfig) return;
        const currentViews = selectedItem.savedViews || [];
        onUpdateItem(selectedItem.id, { 
            savedViews: [...currentViews, { 
                ...selectedItem.spatialConfig,
                explodeFactor: selectedItem.explodeFactor // 核心：捕获时记录爆炸状态
            }] 
        });
    };

    const handleApplyStandardView = (viewAngle: string, config: any) => {
        onUpdateItem(selectedItem.id, { 
            viewAngle: viewAngle as any, 
            spatialConfig: { ...config, explodeFactor: selectedItem.explodeFactor },
            cameraMode: 'orthographic'
        });
    };

    const handleExecuteModelCommand = () => {
        if (!modelCommand.trim()) return;
        onFloatingAction?.(selectedItem.id, `model_cmd:${modelCommand}`);
        setModelCommand('');
    };

    const standardViews = [
        { id: 'front', label: '正 (Front)', config: { azimuth: 0, elevation: 0, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'side', label: '侧 (Side)', config: { azimuth: 90, elevation: 0, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'top', label: '顶 (Top)', config: { azimuth: 0, elevation: 89, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'perspective', label: '透 (Iso)', config: { azimuth: 45, elevation: 35, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
    ];

    return (
        <div className="flex flex-col h-full bg-[#09090b] text-white p-6 overflow-y-auto no-scrollbar pointer-events-auto space-y-8">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <BoxIcon className="w-5 h-5 text-indigo-500"/>
                    <span className="font-black text-[11px] uppercase tracking-[0.2em] text-zinc-100">3D 对象编排器</span>
                </div>
                <button onClick={() => onDelete(selectedItem.id)} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-red-500/10 text-zinc-500 hover:text-red-500 transition-all">
                    <TrashIcon className="w-4 h-4"/>
                </button>
            </div>

            <div className="space-y-3">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <EyeIcon className="w-3.5 h-3.5" /> Camera Projection
                </label>
                <div className="flex bg-zinc-800/50 p-1 rounded-xl gap-1 border border-white/5">
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { cameraMode: 'perspective' })}
                        className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${selectedItem.cameraMode !== 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        透视 (Persp)
                    </button>
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { cameraMode: 'orthographic' })}
                        className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${selectedItem.cameraMode === 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        正交 (Ortho)
                    </button>
                </div>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Model Command Center
                    </label>
                </div>
                <div className="relative group">
                    <textarea 
                        value={modelCommand}
                        onChange={(e) => setModelCommand(e.target.value)}
                        onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleExecuteModelCommand(); } }}
                        className="w-full bg-[#111113] border border-zinc-800 rounded-xl px-4 py-3 text-[12px] h-20 focus:border-indigo-500/50 outline-none resize-none transition-all placeholder:text-zinc-700"
                        placeholder="输入指令: '喷涂零件红色' 或 '高亮指示灯'..."
                    />
                    <button 
                        onClick={handleExecuteModelCommand}
                        className="absolute bottom-2 right-2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all shadow-lg active:scale-95"
                    >
                        <ArrowIcon className="w-3.5 h-3.5" />
                    </button>
                </div>
            </div>

            {/* 随机上色功能区 */}
            <div className="space-y-3">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <PaletteIcon className="w-3.5 h-3.5" /> Material Lab
                </label>
                <button 
                    onClick={() => onFloatingAction?.(selectedItem.id, 'random_cmf')}
                    className="w-full py-4 bg-[#18181b] hover:bg-zinc-800 border border-white/5 text-indigo-400 hover:text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all shadow-lg active:scale-95"
                >
                    <ShuffleIconLucide className="w-4 h-4" /> 随机工业设计 CMF 方案
                </button>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <CameraIcon className="w-3.5 h-3.5" /> Perspective Manager
                    </label>
