            for (const r of pkg.recipes) { await saveRecipe(r); }
            setRecipeRefreshTrigger(prev => prev + 1);
        }
        if (pkg.playstyles) {
            for (const ps of pkg.playstyles) { await savePlaystyle(ps); }
            setPlaystyleRefreshTrigger(prev => prev + 1);
        }
        setSelection([]); 
        setTimeout(() => zoomToFit(), 100); 
    } catch (e: any) { throw e; }
  }, [resetHistory, setView, zoomToFit]);

  const handleExportProject = useCallback(async () => {
