          onCameraChange={(id, s) => handleUpdateItem(id, { spatialConfig: s })}
          onLoadParts={(id, p) => handleUpdateItem(id, { partList: p })}
        />
      </div>

      {isCapturing && captureRect && (
        <div 
          className="fixed inset-0 z-[2000] pointer-events-none"
        >
           <div 
             className="absolute border-2 border-indigo-500 bg-indigo-500/5 shadow-[0_0_0_9999px_rgba(0,0,0,0.4)]"
             style={{ 
               left: captureRect.x * view.scale + view.x, 
               top: captureRect.y * view.scale + view.y, 
               width: captureRect.width * view.scale, 
               height: captureRect.height * view.scale 
             }} 
           />
        </div>
      )}

