import { useRef, useEffect, useState, useMemo, memo } from 'react';
import React from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import { SpatialConfig, PartCMF } from '../types';

interface ModelViewportProps {
  url: string;
  viewAngle?: 'front' | 'top' | 'side' | 'perspective';
  cameraMode?: 'perspective' | 'orthographic';
  explodeFactor?: number;
  activePartId?: string;
  highlightedPartIds?: string[];
  hiddenPartIds?: string[];
  colorSeed?: number;
  partColorMap?: Record<string, string>;
  partCMFMap?: Record<string, PartCMF>;
  onPartSelect?: (partId: string) => void;
  onCameraChange?: (spatial: SpatialConfig) => void;
  onLoadParts?: (parts: string[]) => void;
  width: number;
  height: number;
  spatialConfig?: SpatialConfig;
}

const ModelViewport: React.FC<ModelViewportProps> = memo(({ 
  url, viewAngle = 'perspective', cameraMode, explodeFactor = 0, activePartId, 
  highlightedPartIds = [], hiddenPartIds = [], colorSeed = 0, 
  partColorMap = {}, partCMFMap = {}, onPartSelect, onCameraChange, onLoadParts, width, height, spatialConfig
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);

  const perspectiveCameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const orthoCameraRef = useRef<THREE.OrthographicCamera | null>(null);
  const activeCameraRef = useRef<THREE.Camera | null>(null);

  const groupRef = useRef<THREE.Group | null>(null);
  const controlsRef = useRef<OrbitControls | null>(null);
  const modelBoxRef = useRef<THREE.Box3>(new THREE.Box3());

  const initialPositions = useRef<Map<string, THREE.Vector3>>(new Map());
  const relativeExplodeVectors = useRef<Map<string, THREE.Vector3>>(new Map());
  const partMaterials = useRef<Map<string, THREE.MeshStandardMaterial>>(new Map());

  // 核心：用于快速查找零件的 Map
  const partMap = useRef<Map<string, THREE.Object3D>>(new Map());

  const hashString = (str: string, seed: number = 0) => {
    let hash = seed ^ 0xdeadbeef;
    for (let i = 0; i < str.length; i++) {
      hash = Math.imul(hash ^ str.charCodeAt(i), 2654435761);
    }
    return hash ^ (hash >>> 16);
  };

  // 同步可见性与高亮
  const syncSceneState = () => {
    partMap.current.forEach((obj, id) => {
        // 1. 同步显隐
        const isHidden = hiddenPartIds.includes(id);
        obj.visible = !isHidden;

        // 2. 同步高亮 (仅对 Mesh 有效)
        if ((obj as any).isMesh) {
            const mesh = obj as THREE.Mesh;
            const mat = mesh.material as THREE.MeshStandardMaterial;
            if (mat) {
                const isSelected = activePartId === id;
                const isHighlighted = highlightedPartIds.includes(id);

                if (isSelected) {
                    mat.emissive.set(0x6366f1);
                    mat.emissiveIntensity = 0.8;
                } else if (isHighlighted) {
                    mat.emissive.set(0x4f46e5);
                    mat.emissiveIntensity = 0.5;
                } else {
                    mat.emissive.set(0x000000);
                    mat.emissiveIntensity = 0;
                }
            }
        }
    });
  };

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf4f4f5);
    sceneRef.current = scene;

    const aspect = width / height;
    const pCamera = new THREE.PerspectiveCamera(45, aspect, 0.1, 2000);
    perspectiveCameraRef.current = pCamera;

    const oCamera = new THREE.OrthographicCamera(-10 * aspect, 10 * aspect, 10, -10, 0.1, 2000);
    orthoCameraRef.current = oCamera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.shadowMap.enabled = true;
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
    keyLight.position.set(5, 10, 7.5);
    scene.add(keyLight);

    const loader = new OBJLoader();
    loader.load(url, (obj) => {
      const group = obj;
      groupRef.current = group;
      scene.add(group);

      const box = new THREE.Box3().setFromObject(group);
      modelBoxRef.current = box;
      const center = box.getCenter(new THREE.Vector3());
      const size = box.getSize(new THREE.Vector3());
      group.position.sub(center);

      const parts: string[] = [];
      let meshIdx = 0;
      const meshCenters: { id: string, center: THREE.Vector3, mesh: THREE.Mesh }[] = [];

      group.traverse((child) => {
        if ((child as any).isMesh) {
          const mesh = child as THREE.Mesh;
          // 核心：使用稳定 ID 机制。优先使用模型内部名，没有则使用序号。
          const partId = mesh.name || `Part_${meshIdx++}`;
          mesh.name = partId; // 强制重写以保持一致
          parts.push(partId);

          partMap.current.set(partId, mesh);

          const meshBox = new THREE.Box3().setFromObject(mesh);
          const meshCenter = meshBox.getCenter(new THREE.Vector3());
          meshCenters.push({ id: partId, center: meshCenter, mesh });
          meshCount++;
        }
      });

      onLoadParts?.(parts);

      const logicalCentroid = meshCount > 0 ? center : new THREE.Vector3(0, 0, 0);

      meshCenters.forEach(({ id, mesh, center }) => {
        const material = new THREE.MeshStandardMaterial({ 
            metalness: 0.3, roughness: 0.4, color: new THREE.Color(0xcccccc) 
        });
        mesh.material = material;
        partMaterials.current.set(id, material);
        initialPositions.current.set(id, mesh.position.clone());
        const explodeVec = center.clone().sub(logicalCentroid);
        relativeExplodeVectors.current.set(id, explodeVec);
      });

      const maxDim = Math.max(size.x, size.y, size.z);
      const viewDistance = maxDim * 2.5;

      const useOrtho = cameraMode === 'orthographic' || (viewAngle && ['top', 'front', 'side'].includes(viewAngle));
      const camera = useOrtho ? oCamera : pCamera;
      activeCameraRef.current = camera;

      if (spatialConfig) {
          const phi = (90 - spatialConfig.elevation) * (Math.PI / 180);
          const theta = (spatialConfig.azimuth) * (Math.PI / 180);
          camera.position.setFromSphericalCoords(spatialConfig.distance || viewDistance, phi, theta);
      } else {
          camera.position.set(viewDistance * 0.7, viewDistance * 0.7, viewDistance * 0.7);
      }
      camera.lookAt(0, 0, 0);

      const controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.addEventListener('change', () => {
          if (!activeCameraRef.current || !onCameraChange) return;
          const cam = activeCameraRef.current;
          const spherical = new THREE.Spherical().setFromVector3(cam.position);
          let rawAzi = (spherical.theta * 180 / Math.PI) % 360;
          const azimuth = rawAzi < 0 ? rawAzi + 360 : rawAzi;
          const elevation = 90 - (spherical.phi * 180 / Math.PI);
          onCameraChange({ azimuth, elevation, distance: spherical.radius, fov: (cam as any).fov || 45, explodeFactor });
      });
      controlsRef.current = controls;

      applyCMF();
      syncSceneState(); // 初始同步
    });

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();
    const handleMouseClick = (event: MouseEvent) => {
        if (!containerRef.current || !activeCameraRef.current || !groupRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
        raycaster.setFromCamera(mouse, activeCameraRef.current);

        // 核心：只检测可见零件
        const visibleObjects: THREE.Object3D[] = [];
        groupRef.current.traverse(child => { if (child.visible && (child as any).isMesh) visibleObjects.push(child); });

        const intersects = raycaster.intersectObjects(visibleObjects, true);
        if (intersects.length > 0) { 
            onPartSelect?.(intersects[0].object.name); 
        } else { 
            onPartSelect?.(''); 
        }
    };

    const container = containerRef.current;
    container.addEventListener('click', handleMouseClick);

    let meshCount = 0;
    let frameId: number;
    const animate = (time: number) => {
      frameId = requestAnimationFrame(animate);
      if (controlsRef.current) controlsRef.current.update();
      if (rendererRef.current && sceneRef.current && activeCameraRef.current) {
        rendererRef.current.render(sceneRef.current, activeCameraRef.current);
      }
    };
    animate(0);

    return () => {
      cancelAnimationFrame(frameId);
      container.removeEventListener('click', handleMouseClick);
      renderer.dispose();
      partMap.current.clear();
      partMaterials.current.clear();
      if (renderer.domElement && container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
    };
  }, [url, width, height]);

  useEffect(() => { syncSceneState(); }, [hiddenPartIds, activePartId, highlightedPartIds]);

  const applyCMF = () => {
    partMaterials.current.forEach((mat, partId) => {
      const cmf = partCMFMap[partId];
      if (cmf) {
          if (cmf.color) mat.color.set(cmf.color);
          if (cmf.metalness !== undefined) mat.metalness = cmf.metalness;
          if (cmf.roughness !== undefined) mat.roughness = cmf.roughness;
          if (cmf.opacity !== undefined) { mat.transparent = cmf.opacity < 1; mat.opacity = cmf.opacity; }
          mat.needsUpdate = true;
      } else {
        const hash = hashString(partId, colorSeed);
        const hue = (Math.abs(hash) * 137.508) % 360;
        mat.color.setHSL(hue / 360, 0.65, 0.55);
      }
    });
  };

  useEffect(() => { applyCMF(); }, [colorSeed, partCMFMap]);

  useEffect(() => {
    if (!groupRef.current) return;
    partMap.current.forEach((obj, id) => {
        if ((obj as any).isMesh) {
            const initial = initialPositions.current.get(id);
            const relVec = relativeExplodeVectors.current.get(id);
            if (initial && relVec) {
              const offset = relVec.clone().multiplyScalar(explodeFactor * 4); 
              obj.position.copy(initial).add(offset);
            }
        }
    });
  }, [explodeFactor]);

  return <div ref={containerRef} className="w-full h-full" style={{ touchAction: 'none' }} />;
}, (prev, next) => {
  return prev.url === next.url && 
         prev.viewAngle === next.viewAngle && 
         prev.cameraMode === next.cameraMode && 
         prev.explodeFactor === next.explodeFactor && 
         prev.activePartId === next.activePartId && 
         JSON.stringify(prev.highlightedPartIds) === JSON.stringify(next.highlightedPartIds) &&
         JSON.stringify(prev.hiddenPartIds) === JSON.stringify(next.hiddenPartIds) &&
         prev.colorSeed === next.colorSeed && 
         JSON.stringify(prev.partCMFMap) === JSON.stringify(next.partCMFMap) &&
         prev.width === next.width &&
         prev.height === next.height &&
         JSON.stringify(prev.spatialConfig) === JSON.stringify(next.spatialConfig);
});

export default ModelViewport;

import { useState, useEffect, useMemo, useRef } from 'react';
import React from 'react';
import { CanvasItem, ItemType, EditToolType, GenerationSettings, SpatialConfig, IdentifiedPoint } from '../types';
import { 
  SparklesIcon, RefreshIcon, EraserIcon, 
  ScissorsIcon, VectorIcon, 
  UpscaleIcon, SlidersIcon, ChevronRightIcon,
  ChevronLeftIcon, SquareIcon, TrashIcon,
  FileIcon, CopyIcon, EvolutionIcon,
  LassoIcon, BrushIcon, TypeIcon, CreativeScaleIcon, ZapIcon,
  PaletteIcon, XIcon, FocusIcon,
  MessageCircleIcon, TargetIcon, WandIcon, LinkIcon, CameraIcon,
  MaximizeIcon, BoxIcon, CheckIcon, RotateCcwIcon, MagicCurveIcon,
  MergeIcon, FrameIcon, ExpandIcon, LayoutGridIcon, GripIcon, ShuffleIcon,
  GalleryIcon, TerminalIcon, PlusIcon,
  ArrowIcon, FlaskIcon, EyeIcon, EyeOffIcon, ShuffleIcon as ShuffleIconLucide,
  SearchIcon, ListIcon
} from './Icons';
import SpatialController from './SpatialController';
import { getEvolutionStage } from '../services/evolutionService';

type PanelView = 'main' | 'variations' | 'edit_area' | 'adjust_colors' | 'change_bg' | 'evolution' | 'spatial' | 'transplant' | 'model_3d';

interface PropertiesPanelProps {
  selectedItem: CanvasItem | null;
  selectedItems?: CanvasItem[];
  onUpdateItem: (id: string, updates: Partial<CanvasItem>) => void;
  onGenerate: (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>) => void;
  onDelete: (id: string) => void;
  onAutoPrompt?: (id: string) => Promise<void>;
  onEnterEditMode?: (tool: EditToolType) => void;
  onExitEditMode?: () => void;
  initialView?: {view: string, ts: number} | null;
  onSendToPrompt?: (id: string) => void;
  onSendToGemini?: (id: string) => void;
  onSyncPointsToGemini?: (id: string) => void;
  onFrameAction?: (id: string, action: 'merge' | 'expand' | 'crop') => void;
  editTool?: EditToolType;
  setEditTool?: (tool: EditToolType) => void;
  brushSize?: number;
  setBrushSize?: (size: number) => void;
  onApplyEdit?: (prompt: string) => void;
  onClearMask?: () => void;
  onJSONAnalysis?: (id: string) => void;
  isAnalyzingJSON?: boolean;
  onStartPickPoint?: (id: string, temperature: number) => void;
  isPickingPoint?: boolean;
  currentEvolutionLevel?: number;
  isCncMode: boolean;
  setIsCncMode: (val: boolean) => void;
  onUpdatePoint?: (itemId: string, pointId: string, updates: Partial<IdentifiedPoint>) => void;
  onClearAllPoints?: (itemId: string) => void;
  onCommitPointChanges?: (itemId: string) => void;
  onAutoAlign?: (sourceId: string, targetId: string) => Promise<void>;
  onClosePanel?: () => void;
  onFloatingAction?: (id: string, action: string) => void;
}

const DEFAULT_SPATIAL: SpatialConfig = {
    azimuth: 45,
    elevation: 30,
    distance: 12,
    fov: 45
};

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ 
  selectedItem, selectedItems = [], onUpdateItem, onGenerate, onDelete, onAutoPrompt, 
  onEnterEditMode, onExitEditMode, initialView, onSendToPrompt, onSendToGemini, onSyncPointsToGemini,
  onFrameAction, editTool, setEditTool, brushSize = 30, setBrushSize, onApplyEdit, onClearMask,
  onJSONAnalysis, isAnalyzingJSON, onStartPickPoint, isPickingPoint, currentEvolutionLevel = 60,
  isCncMode, setIsCncMode, onUpdatePoint, onClearAllPoints, onCommitPointChanges, onAutoAlign, onClosePanel,
  onFloatingAction
}) => {
  const [currentView, setCurrentView] = useState<PanelView>('main');
  const [localPrompt, setLocalPrompt] = useState('');
  const [modelCommand, setModelCommand] = useState('');
  const [activeTab, setActiveTab] = useState<'actions' | 'details' | 'nodes'>('actions');
  const [artisticLevel, setArtisticLevel] = useState(currentEvolutionLevel);
  const [pickTemperature, setPickTemperature] = useState(0.8);
  const [isAligning, setIsAligning] = useState(false);
  const [isSwapped, setIsSwapped] = useState(false); 
  const [usePro, setUsePro] = useState(false);
  const [partSearch, setPartSearch] = useState('');

  const textInputRef = useRef<HTMLTextAreaElement>(null);

  const currentStage = useMemo(() => getEvolutionStage(artisticLevel), [artisticLevel]);

  const isTransplantMode = useMemo(() => {
    return selectedItems.length === 2 && selectedItems.every(i => i.type === ItemType.IMAGE);
  }, [selectedItems]);

  useEffect(() => {
    if (initialView) {
        setCurrentView(initialView.view as PanelView);
        if (initialView.view === 'edit_area') onEnterEditMode?.('brush');
    } else {
        setCurrentView('main');
    }
  }, [initialView?.ts, selectedItem?.id]);

  useEffect(() => {
    if (selectedItem) setLocalPrompt(selectedItem.prompt || '');
    if (selectedItem?.type === ItemType.TEXT) {
        setTimeout(() => {
            textInputRef.current?.focus();
            if (selectedItem.content === '在此输入内容') {
                textInputRef.current?.select();
            }
        }, 100);
    }
  }, [selectedItem?.id, selectedItem?.prompt, selectedItem?.type]);

  useEffect(() => {
    setArtisticLevel(currentEvolutionLevel);
  }, [currentEvolutionLevel]);

  const handleAutoAlignInternal = async (targetId: string, sourceId: string) => {
    if (!onAutoAlign) return;
    setIsAligning(true);
    try {
      await onAutoAlign(sourceId, targetId);
    } finally {
      setIsAligning(false);
    }
  };

  const handleFontSizeChange = (size: number) => {
    if (selectedItem) {
      onUpdateItem(selectedItem.id, { fontSize: size });
    }
  };

  if (!selectedItem && !isTransplantMode) {
    return (
      <div className="w-full h-full bg-[#09090b] border border-zinc-800 rounded-[24px] p-8 flex flex-col items-center justify-center text-zinc-500 shadow-2xl">
         <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-zinc-800/50 rounded-[20px] flex items-center justify-center mx-auto border border-zinc-700/50">
                <SparklesIcon className="w-8 h-8 text-indigo-400 opacity-50" />
            </div>
            <div className="space-y-2">
                <h3 className="font-black text-white text-[12px] uppercase tracking-[0.2em]">工作台</h3>
                <p className="text-[11px] text-zinc-500 leading-relaxed max-w-[180px] mx-auto">选择一个画框、图像或 3D 模型来编辑其属性、生成变体或应用空间控制。</p>
            </div>
         </div>
      </div>
    );
  }

  const handleBack = () => {
    setCurrentView('main');
    onExitEditMode?.();
  };

  const renderModelPanel = () => {
    if (!selectedItem || selectedItem.type !== ItemType.MODEL) return null;

    const hiddenIds = selectedItem.hiddenPartIds || [];
    const partList = selectedItem.partList || [];

    const filteredParts = partList.filter(p => p.toLowerCase().includes(partSearch.toLowerCase()));

    const handleCaptureView = () => {
        if (!selectedItem.spatialConfig) return;
        const currentViews = selectedItem.savedViews || [];
        onUpdateItem(selectedItem.id, { 
            savedViews: [...currentViews, { 
                ...selectedItem.spatialConfig,
                explodeFactor: selectedItem.explodeFactor 
            }] 
        });
    };

    const handleTogglePartVisibility = (partId: string) => {
        const nextHidden = hiddenIds.includes(partId) 
            ? hiddenIds.filter(id => id !== partId) 
            : [...hiddenIds, partId];
        onUpdateItem(selectedItem.id, { hiddenPartIds: nextHidden });
    };

    const handleResetVisibility = () => {
        onUpdateItem(selectedItem.id, { hiddenPartIds: [] });
    };

    const handleApplyStandardView = (viewAngle: string, config: any) => {
        onUpdateItem(selectedItem.id, { 
            viewAngle: viewAngle as any, 
            spatialConfig: { ...config, explodeFactor: selectedItem.explodeFactor },
            cameraMode: 'orthographic'
        });
    };

    const handleExecuteModelCommand = () => {
        if (!modelCommand.trim()) return;
        onFloatingAction?.(selectedItem.id, `model_cmd:${modelCommand}`);
        setModelCommand('');
    };

    const standardViews = [
        { id: 'front', label: '正 (Front)', config: { azimuth: 0, elevation: 0, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'side', label: '侧 (Side)', config: { azimuth: 90, elevation: 0, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'top', label: '顶 (Top)', config: { azimuth: 0, elevation: 89, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'perspective', label: '透 (Iso)', config: { azimuth: 45, elevation: 35, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
    ];

    return (
        <div className="flex flex-col h-full bg-[#09090b] text-white p-6 overflow-y-auto no-scrollbar pointer-events-auto space-y-8 pb-20">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <BoxIcon className="w-5 h-5 text-indigo-500"/>
                    <span className="font-black text-[11px] uppercase tracking-[0.2em] text-zinc-100">3D 对象编排器</span>
                </div>
                <button onClick={() => onDelete(selectedItem.id)} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-red-500/10 text-zinc-500 hover:text-red-500 transition-all">
                    <TrashIcon className="w-4 h-4"/>
                </button>
            </div>

            {/* AI 指令区 */}
            <div className="space-y-4">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Model Command Center
                </label>
                <div className="relative group">
                    <textarea 
                        value={modelCommand}
                        onChange={(e) => setModelCommand(e.target.value)}
                        onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleExecuteModelCommand(); } }}
                        className="w-full bg-[#111113] border border-zinc-800 rounded-xl px-4 py-3 text-[12px] h-20 focus:border-indigo-500/50 outline-none resize-none transition-all placeholder:text-zinc-700"
                        placeholder="输入指令: '喷涂零件红色' 或 '隐藏内部件'..."
                    />
                    <button 
                        onClick={handleExecuteModelCommand}
                        className="absolute bottom-2 right-2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all shadow-lg active:scale-95"
                    >
                        <ArrowIcon className="w-3.5 h-3.5" />
                    </button>
                </div>
            </div>

            {/* 零件管理区 */}
            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <ListIcon className="w-3.5 h-3.5 text-indigo-400" /> 零件清单 ({partList.length})
                    </label>
                    <button 
                        onClick={handleResetVisibility}
                        className="text-[9px] font-black text-indigo-400 hover:text-indigo-300 uppercase tracking-widest"
                    >
                        全部显示
                    </button>
                </div>

                <div className="relative">
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-zinc-600" />
                    <input 
                        value={partSearch}
                        onChange={(e) => setPartSearch(e.target.value)}
                        className="w-full bg-[#111113] border border-zinc-800 rounded-lg pl-9 pr-3 py-2 text-[11px] text-zinc-300 outline-none focus:border-indigo-500/30 transition-all"
                        placeholder="搜索零件名称..."
                    />
                </div>

                <div className="bg-[#111113] border border-zinc-800 rounded-xl overflow-hidden max-h-[220px] overflow-y-auto no-scrollbar">
                    {filteredParts.length === 0 ? (
                        <div className="py-4 text-center text-[10px] text-zinc-700 font-bold uppercase tracking-widest">无匹配项</div>
                    ) : (
                        filteredParts.map(p => {
                            const isSelectedInScene = selectedItem.activePartId === p;
                            return (
                                <div key={p} className={`flex items-center justify-between px-4 py-2.5 border-b border-white/5 last:border-0 group/part transition-colors ${isSelectedInScene ? 'bg-indigo-600/20 border-l-2 border-l-indigo-500' : 'hover:bg-white/5'}`}>
                                    <div className="flex items-center gap-2 min-w-0 flex-1">
                                        <div className="w-1.5 h-1.5 rounded-full shrink-0 shadow-[0_0_5px_rgba(0,0,0,0.5)]" style={{ backgroundColor: selectedItem.partCMFMap?.[p]?.color || '#666' }} />
                                        <span className={`text-[11px] font-bold truncate ${hiddenIds.includes(p) ? 'text-zinc-700 line-through' : isSelectedInScene ? 'text-indigo-400' : 'text-zinc-300'}`}>{p}</span>
                                    </div>
                                    <button 
                                        onClick={() => handleTogglePartVisibility(p)}
                                        className={`p-1.5 rounded-lg transition-all ${hiddenIds.includes(p) ? 'text-zinc-600 hover:text-white bg-white/5' : 'text-zinc-500 hover:text-indigo-400'}`}
                                    >
                                        {hiddenIds.includes(p) ? <EyeOffIcon className="w-3.5 h-3.5" /> : <EyeIcon className="w-3.5 h-3.5" />}
                                    </button>
                                </div>
                            );
                        })
                    )}
                </div>
            </div>

            <div className="space-y-3">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <PaletteIcon className="w-3.5 h-3.5" /> Material Lab
                </label>
                <button 
                    onClick={() => onFloatingAction?.(selectedItem.id, 'random_cmf')}
                    className="w-full py-4 bg-[#18181b] hover:bg-zinc-800 border border-white/5 text-indigo-400 hover:text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 transition-all shadow-lg active:scale-95"
                >
                    <ShuffleIconLucide className="w-4 h-4" /> 随机工业设计 CMF 方案
                </button>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <CameraIcon className="w-3.5 h-3.5" /> Perspective Manager
                    </label>
                    <button 
                        onClick={handleCaptureView}
                        className="p-1.5 bg-indigo-500/10 text-indigo-400 hover:bg-indigo-500/20 rounded-lg border border-indigo-500/20 transition-all"
                        title="捕获自定义视角"
                    >
                        <PlusIcon className="w-3.5 h-3.5" />
                    </button>
                </div>

                <div className="grid grid-cols-2 gap-2">
                    {standardViews.map(sv => (
                        <button 
                            key={sv.id}
                            onClick={() => handleApplyStandardView(sv.id, sv.config)}
                            className={`py-2.5 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 ${selectedItem.viewAngle === sv.id ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-zinc-800/50 border-white/5 text-zinc-500 hover:bg-zinc-700 hover:text-white'}`}
                        >
                            {sv.label}
                        </button>
                    ))}
                </div>

                <div className="h-px bg-white/5 my-2" />

                <div className="grid grid-cols-4 gap-2">
                    {selectedItem.savedViews?.map((v, i) => (
                        <button 
                            key={i}
                            onClick={() => onUpdateItem(selectedItem.id, { 
                                spatialConfig: v,
                                explodeFactor: v.explodeFactor ?? selectedItem.explodeFactor 
                            })}
                            className={`aspect-square rounded-xl bg-[#18181b] border flex items-center justify-center text-[10px] font-black transition-all ${JSON.stringify(selectedItem.spatialConfig) === JSON.stringify(v) ? 'border-indigo-500 text-indigo-400 bg-indigo-500/5' : 'border-white/5 text-zinc-500 hover:border-white/10'}`}
                        >
                            V{i+1}
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-5">
                <div className="flex justify-between items-center px-1">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">物理爆炸强度</label>
                    <span className="text-indigo-400 font-mono text-[11px] font-black bg-indigo-500/10 px-2 py-0.5 rounded-md border border-indigo-500/20">{Math.round((selectedItem.explodeFactor || 0) * 100)}%</span>
                </div>
                <input 
                    type="range" min="0" max="1" step="0.01"
                    value={selectedItem.explodeFactor || 0}
                    onChange={(e) => onUpdateItem(selectedItem.id, { explodeFactor: Number(e.target.value) })}
                    className="w-full h-1 bg-zinc-800 rounded-lg appearance-none accent-indigo-500 cursor-pointer"
                />
            </div>
        </div>
    );
  };

  const renderTransplantPanel = () => {
    const targetImg = isSwapped ? selectedItems[1] : selectedItems[0];
    const sourceImg = isSwapped ? selectedItems[0] : selectedItems[1];
    const targetPoints = targetImg.identifiedPoints || [];
    const sourcePoints = sourceImg.identifiedPoints || [];

    return (
        <div className="flex flex-col h-full animate-in fade-in duration-500 bg-[#09090b]">
            <div className="p-6 border-b border-zinc-800 flex flex-col gap-5">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <MagicCurveIcon className="w-5 h-5 text-indigo-400" />
                        <span className="font-black text-[12px] uppercase tracking-[0.2em] text-white">跨图设计移植</span>
                    </div>
                </div>

                <div className="flex gap-4 relative items-center">
                    <div className={`flex-1 p-2 rounded-2xl border transition-all duration-500 ${!isSwapped ? 'bg-white/5 border-indigo-500/30 ring-1 ring-indigo-500/20 shadow-[0_0_20px_rgba(99,102,241,0.1)]' : 'bg-black border-white/5 opacity-50'}`}>
                        <div className="flex items-center justify-between mb-1.5 px-1">
                            <span className={`text-[9px] font-black uppercase tracking-widest ${!isSwapped ? 'text-indigo-400' : 'text-zinc-500'}`}>结构 (Target)</span>
                        </div>
                        <div className="aspect-video rounded-xl bg-black overflow-hidden relative border border-white/5 shadow-inner">
                            <img src={isSwapped ? selectedItems[1].content : selectedItems[0].content} className="w-full h-full object-cover" />
                        </div>
                    </div>

                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-20">
                        <button 
                            onClick={() => setIsSwapped(!isSwapped)}
                            className="w-10 h-10 rounded-full bg-indigo-600 border-4 border-[#09090b] text-white flex items-center justify-center shadow-[0_8px_24px_rgba(0,0,0,0.8)] hover:scale-110 active:rotate-180 transition-all duration-500 hover:bg-indigo-500"
                            title="互换角色"
                        >
                            <RefreshIcon className="w-5 h-5" />
                        </button>
                    </div>

                    <div className={`flex-1 p-2 rounded-2xl border transition-all duration-500 ${isSwapped ? 'bg-white/5 border-indigo-500/30 ring-1 ring-indigo-500/20 shadow-[0_0_20px_rgba(99,102,241,0.1)]' : 'bg-black border-white/5 opacity-50'}`}>
                        <div className="flex items-center justify-between mb-1.5 px-1">
                            <span className={`text-[9px] font-black uppercase tracking-widest ${isSwapped ? 'text-indigo-400' : 'text-zinc-500'}`}>审美 (Source)</span>
                        </div>
                        <div className="aspect-video rounded-xl bg-black overflow-hidden relative border border-white/5 shadow-inner">
                            <img src={isSwapped ? selectedItems[0].content : selectedItems[1].content} className="w-full h-full object-cover" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto no-scrollbar p-6 space-y-6">
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">特征配对细节</span>
                        <button 
                            onClick={() => handleAutoAlignInternal(targetImg.id, sourceImg.id)}
                            disabled={isAligning || targetPoints.length === 0 || sourcePoints.length === 0}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${isAligning ? 'bg-indigo-600 animate-pulse text-white' : 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 hover:bg-indigo-500/20'}`}
                        >
                            {isAligning ? <RefreshIcon className="w-3 h-3 animate-spin" /> : <SparklesIcon className="w-3 h-3" />}
                            语义自动对齐
                        </button>
                    </div>

                    <div className="space-y-4">
                        {targetPoints.map(p => {
                            const pairedPoint = sourcePoints.find(sp => sp.id === p.pairingId);
                            return (
                                <div key={p.id} className="p-4 bg-[#111113] rounded-2xl border border-white/5 flex flex-col gap-4 shadow-sm hover:border-white/10 transition-all group/item">
                                    <div className="flex items-start gap-3">
                                        <div className="w-6 h-6 rounded-lg bg-zinc-800 flex items-center justify-center text-[10px] font-black text-white shrink-0 mt-0.5">
                                            {p.label}
                                        </div>
                                        <div className="flex flex-col min-w-0 flex-1">
                                            <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Target 结构件</span>
                                            <span className="text-[12px] font-bold text-zinc-100 break-all leading-snug">{p.description}</span>
                                        </div>
                                    </div>

                                    <div className="flex items-start gap-3 ml-2 border-l border-zinc-800/80 pl-4">
                                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 shrink-0 shadow-[0_0_10px_rgba(99,102,241,0.5)] mt-3.5" />
                                        {pairedPoint ? (
                                            <div className="flex-1 flex items-start justify-between min-w-0 bg-indigo-500/5 px-4 py-3 rounded-xl border border-indigo-500/10 transition-all group-hover/item:border-indigo-500/30">
                                                <div className="flex flex-col min-w-0 flex-1">
                                                    <span className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">审美映射源 (Source)</span>
                                                    <span className="text-[12px] font-bold text-indigo-100 truncate">[{pairedPoint.label}] {pairedPoint.description}</span>
                                                </div>
                                                <button onClick={() => onUpdatePoint?.(targetImg.id, p.id, { pairingId: undefined, pairingSourceItemId: undefined })} className="p-1 text-zinc-600 hover:text-red-500 transition-colors">
                                                    <TrashIcon className="w-3 h-3" />
                                                </button>
                                            </div>
                                        ) : (
                                            <div className="flex-1 py-3 px-4 rounded-xl border border-dashed border-zinc-800 text-[10px] font-medium text-zinc-600">
                                                未配对特征点
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            <div className="p-6 bg-[#0c0c0e] border-t border-zinc-800">
                <button 
                    onClick={() => onCommitPointChanges?.(targetImg.id)}
                    disabled={targetPoints.filter(p => p.pairingId).length === 0}
                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-[12px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-[0.98] flex items-center justify-center gap-3 disabled:opacity-30 disabled:grayscale"
                >
                    <SparklesIcon className="w-4 h-4" /> 执行设计移植 (Pro)
                </button>
            </div>
        </div>
    );
  };

  const renderPointNodes = () => {
    if (!selectedItem) return null;
    const points = selectedItem.identifiedPoints || [];

    const hasChanges = points.some(p => 
        p.isRemoving || 
        (p.modifiedDescription && p.modifiedDescription !== p.description) || 
        p.pairingId || 
        (p.originalPos && (Math.abs(p.originalPos[0] - p.y) > 1 || Math.abs(p.originalPos[1] - p.x) > 1))
    );

    return (
        <div className="space-y-5 animate-in fade-in slide-in-from-bottom-2 duration-400">
            <div className="flex items-center justify-between px-1">
                <div className="flex flex-col">
                    <span className="text-[11px] font-black text-white uppercase tracking-widest">特征点管理器</span>
